def _log_crash(exc: BaseException):
    tb = traceback.format_exc()
    print("\n" + "!" * 60)
    print("  FATAL ERROR")
    print("!" * 60)
    print(tb)
    for folder in (MEDIA_ROOT, LIB_ROOT):
        try:
            os.makedirs(folder, exist_ok=True)
            log_path = os.path.join(folder, "error_log.txt")
            with open(log_path, "a", encoding="utf-8") as f:
                f.write("\n" + "=" * 80 + "\n" + tb + "\n")
            print(f"  Saved: {log_path}")
            break
        except Exception:
            continue
    _pause_exit(1)


def _count_files(folder: str) -> int:
    n = 0
    try:
        for root, dirs, files in os.walk(folder):
            n += len(files)
    except Exception:
        pass
    return n


def _package_importable(imp_name: str, extra_path: str = "") -> bool:
    """Return True only if Python can actually import the module."""
    code = (
        "import sys, importlib; "
        "p=sys.argv[1]; "
        "sys.path.insert(0,p) if p and p not in sys.path else None; "
        f"importlib.import_module({imp_name!r})"
    )
    try:
        result = subprocess.run(
            [sys.executable, "-c", code, extra_path or ""],
            capture_output=True,
            text=True,
            timeout=30,
            cwd=MEDIA_ROOT if os.path.isdir(MEDIA_ROOT) else None,
        )
        return result.returncode == 0
    except Exception:
        return False


def _install_once(pip_name: str, target: str, label: str = "") -> bool:
    """Install only when an actual import test fails. Never called when import works."""
    try:
        os.makedirs(target, exist_ok=True)
        print(f"  [..] Installing {label or pip_name} into {target}")
        subprocess.check_call([
            sys.executable, "-m", "pip", "install",
            "--disable-pip-version-check",
            "--no-warn-script-location",
            "--target", target,
            pip_name,
        ])
        importlib.invalidate_caches()
        return True
    except Exception as e:
        print(f"  [WARN] Failed to install {pip_name}: {e}")
        return False


def _mask_user_id(user_id: str) -> str:
    """Never print full emails / account ids in console logs."""
    uid = (user_id or "").strip()
    if not uid:
        return "unknown"
    if "@" in uid:
        local, _, domain = uid.partition("@")
        if len(local) <= 2:
            return f"**@{domain}"
        return f"{local[:2]}***@{domain}"
    if len(uid) <= 4:
        return "***"
    return f"{uid[:2]}***{uid[-2:]}"


def extract_api_keys() -> list:
    text = USER_CONFIG or ""
    keys = []
    seen = set()
    pat_numbered = re.compile(
        r"(?m)^\s*(\d+)\s*[\.\)]\s*"
        r"(?:Enter\s+)?Groq\s+API\s+Key"
        r"(?:\s*\(\s*userID\s*:\s*([^)]+?)\s*\))?"
        r"\s*:\s*"
        r"(\S+)",
        re.IGNORECASE,
    )
    for m in pat_numbered.finditer(text):
        idx = int(m.group(1))
        uid = (m.group(2) or "").strip()
        key = m.group(3).strip()
        up = key.upper()
        if any(p in up for p in ("PASTE", "YOUR_GROQ", "YOUR_KEY", "REPLACE_ME", "XYZ")):
            continue
        if key.lower() in ("YOUR_GROQ_API_KEY_REDACTED", "YOUR_GROQ_API_KEY_REDACTED_key_here", "YOUR_GROQ_API_KEY_REDACTED"):
            continue
        if not key.lower().startswith("gsk_"):
            continue
        if len(key) < 20:
            continue
        if key in seen:
            continue
        seen.add(key)
        keys.append({"index": idx, "user_id": uid, "key": key})
    if keys:
        keys.sort(key=lambda d: d["index"])
        for i, d in enumerate(keys, start=1):
            d["slot"] = i
        return keys
    for m in re.finditer(r"(gsk_[A-Za-z0-9_\-]{20,})", text, re.IGNORECASE):
        key = m.group(1).strip()
        if key in seen:
            continue
        up = key.upper()
        if any(p in up for p in ("PASTE", "YOUR", "XYZ")):
            continue
        if key.lower() in ("YOUR_GROQ_API_KEY_REDACTED", "YOUR_GROQ_API_KEY_REDACTED_key_here", "YOUR_GROQ_API_KEY_REDACTED"):
            continue
        seen.add(key)
        keys.append({"index": len(keys) + 1, "user_id": "", "key": key, "slot": len(keys) + 1})
    if not keys:
        env = (os.environ.get("GROQ_API_KEY") or "").strip()
        if env.startswith("gsk_") and len(env) > 20:
            keys.append({"index": 1, "user_id": "ENV:GROQ_API_KEY", "key": env, "slot": 1})
    return keys


