def model_chain(primary_key: str) -> List[str]:
    primary = GROQ_MODELS.get(primary_key) or ""
    fbs = GROQ_MODELS.get(f"{primary_key}_fallbacks") or []
    out = []
    for m in [primary] + list(fbs):
        m = (m or "").strip()
        if not m or m in out or m in _MODEL_DEAD:
            continue
        if _LIVE_MODEL_IDS and m not in _LIVE_MODEL_IDS and m != primary:
            continue
        out.append(m)
    if not out and primary:
        out = [primary]
    if primary_key == "vision" and _LIVE_MODEL_IDS:
        for m in sorted(_LIVE_MODEL_IDS):
            low = m.lower()
            if m in out or m in _MODEL_DEAD:
                continue
            if any(x in low for x in ("qwen3.6", "qwen/qwen3.6", "vision", "llava")):
                out.append(m)
    return out


def mark_model_dead(model_id: str, err: Exception = None):
    if not model_id:
        return
    _MODEL_DEAD.add(model_id)
    msg = f"model marked unavailable this session: {model_id}"
    if err is not None:
        msg += f" | {err}"
    log_error(msg)
    print(f"  {C.YELLOW}[model] Skipping '{model_id}' for rest of run (not found / no access){C.RESET}")


def is_model_not_found_error(e: Exception) -> bool:
    msg = str(e).lower()
    if "model_not_found" in msg:
        return True
    if "does not exist" in msg and "model" in msg:
        return True
    if "do not have access" in msg and "model" in msg:
        return True
    if "decommissioned" in msg:
        return True
    if "invalid_request_error" in msg and "model" in msg and ("404" in msg or "not found" in msg):
        return True
    status = None
    for attr in ("status_code", "status"):
        if hasattr(e, attr):
            try:
                status = int(getattr(e, attr))
            except Exception:
                pass
    if status == 404 and "model" in msg:
        return True
    return False


def strip_code_fences(text: str) -> str:
    if not text:
        return ""
    s = text.strip()
    s = re.sub(r"<think>[\s\S]*?</think>", "", s, flags=re.IGNORECASE)
    s = re.sub(r"<thinking>[\s\S]*?</thinking>", "", s, flags=re.IGNORECASE)
    s = re.sub(r"^```(?:json|JSON)?\s*", "", s)
    s = re.sub(r"\s*```\s*$", "", s)
    return s.strip()


def extract_json_object(text: str) -> Optional[dict]:
    if not text:
        return None
    raw = strip_code_fences(text)
    try:
        obj = json.loads(raw)
        if isinstance(obj, dict):
            return obj
    except Exception:
        pass
    s, e = raw.find("{"), raw.rfind("}")
    if s != -1 and e > s:
        chunk = raw[s : e + 1]
        for candidate in (
            chunk,
            re.sub(r",\s*}", "}", re.sub(r",\s*]", "]", chunk)),
            chunk.replace("\u201c", '"').replace("\u201d", '"').replace("\u2018", "'").replace("\u2019", "'"),
        ):
            try:
                obj = json.loads(candidate)
                if isinstance(obj, dict):
                    return obj
            except Exception:
                pass
    start = raw.find("{")
    if start == -1:
        return None
    depth = 0
    in_str = False
    esc = False
    for i in range(start, len(raw)):
        ch = raw[i]
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                try:
                    obj = json.loads(raw[start : i + 1])
                    if isinstance(obj, dict):
                        return obj
                except Exception:
                    return None
    return None


def normalize_english_field(original: str, english: str) -> str:
    eng = (english or "").strip()
    orig = (original or "").strip()
    if not eng:
        return "Not Required"
    if eng.lower() in ("not required", "n/a", "na", "none", "same", "-"):
        return "Not Required"
    if orig and orig.lower() == eng.lower():
        return "Not Required"
    return eng


def message_text_from_response(resp) -> str:
    try:
        msg = resp.choices[0].message
    except Exception:
        return ""
    content = getattr(msg, "content", None)
    if isinstance(content, str) and content.strip():
        return content
    if isinstance(content, list):
        parts = []
        for p in content:
            if isinstance(p, dict):
                if p.get("type") in ("text", "output_text") and p.get("text"):
                    parts.append(str(p.get("text")))
                elif p.get("text"):
                    parts.append(str(p.get("text")))
            else:
                t = getattr(p, "text", None)
                if t:
                    parts.append(str(t))
        if parts:
            return "\n".join(parts)
    return (content or "") if isinstance(content, str) else ""


class ApiKeyRotator:
    KEY_SWITCH_DELAY_SECONDS = KEY_SWITCH_DELAY_SECONDS

    def __init__(
        self,
        key_entries: list,
        rpm_limit: int = GROQ_RPM_LIMIT,
        rpd_limit: int = GROQ_RPD_LIMIT,
        tpm_limit: int = GROQ_TPM_LIMIT,
        provider_name: str = "Groq",
    ):
        if not key_entries:
            raise ValueError("No API keys provided to ApiKeyRotator")
        self.provider = provider_name
        self.rpm_limit = rpm_limit
        self.rpd_limit = rpd_limit
        self.tpm_limit = tpm_limit
        self.rpm_rotate_at = max(1, rpm_limit - 1)
        self.rpd_rotate_at = max(1, rpd_limit - 1)
        self.tpm_rotate_at = max(1, tpm_limit - 1)
        self._lock = threading.RLock()
        self.keys = []
        for i, entry in enumerate(key_entries):
            self.keys.append({
                "slot": entry.get("slot", i + 1),
                "index": entry.get("index", i + 1),
                "user_id": entry.get("user_id") or f"key#{i + 1}",
                "key": entry["key"],
                "req_times": deque(),
                "tok_events": deque(),
                "day_stamp": self._today(),
                "day_count": 0,
                "total_requests": 0,
                "total_tokens_est": 0,
                "cooldown_until": 0.0,
                "disabled": False,
                "last_error": "",
            })
        self.current_idx = 0
        self._clients = {}
        self._last_switched_from = None

    @staticmethod
    def _today() -> str:
        return datetime.now().strftime("%Y-%m-%d")

    def _purge_windows(self, k: dict, now: float):
        cutoff = now - 60.0
        while k["req_times"] and k["req_times"][0] < cutoff:
            k["req_times"].popleft()
        while k["tok_events"] and k["tok_events"][0][0] < cutoff:
            k["tok_events"].popleft()
        today = self._today()
        if k["day_stamp"] != today:
            k["day_stamp"] = today
            k["day_count"] = 0

    def _rpm(self, k: dict, now: float) -> int:
        self._purge_windows(k, now)
        return len(k["req_times"])

    def _tpm(self, k: dict, now: float) -> int:
        self._purge_windows(k, now)
        return sum(t for _, t in k["tok_events"])

    def _rpd(self, k: dict, now: float) -> int:
        self._purge_windows(k, now)
        return k["day_count"]

    def _is_available(self, k: dict, now: float) -> bool:
        if k["disabled"] or k["cooldown_until"] > now:
            return False
        self._purge_windows(k, now)
        if self._rpm(k, now) >= self.rpm_rotate_at:
            return False
        if self._rpd(k, now) >= self.rpd_rotate_at:
            return False
        if self._tpm(k, now) >= self.tpm_rotate_at:
            return False
        return True

    def _reason_unavailable(self, k: dict, now: float) -> str:
        if k["disabled"]:
            return f"disabled ({k.get('last_error') or 'auth/permanent'})"
        if k["cooldown_until"] > now:
            return f"cooldown {k['cooldown_until'] - now:.1f}s left"
        rpm, rpd, tpm = self._rpm(k, now), self._rpd(k, now), self._tpm(k, now)
        parts = []
        if rpm >= self.rpm_rotate_at:
            parts.append(f"RPM {rpm}/{self.rpm_limit}")
        if rpd >= self.rpd_rotate_at:
            parts.append(f"RPD {rpd}/{self.rpd_limit}")
        if tpm >= self.tpm_rotate_at:
            parts.append(f"TPM~{tpm}/{self.tpm_limit}")
        return ", ".join(parts) or "unknown"

    def _advance(self, from_idx: int) -> int:
        return (from_idx + 1) % len(self.keys)

    def _apply_key_switch_delay(self, old_slot: int, new_slot: int, reason: str = "") -> None:
        delay = max(0, int(self.KEY_SWITCH_DELAY_SECONDS))
        if delay <= 0 or old_slot == new_slot:
            return
        reason_s = f" ({reason})" if reason else ""
        print(
            f"  {C.YELLOW}[{self.provider}] Waiting {delay}s before next key "
            f"#{old_slot} → #{new_slot}{reason_s}...{C.RESET}"
        )
        time.sleep(delay)

    def _pick_index(self, now: float) -> int:
        n = len(self.keys)
        idx = self.current_idx
        for _ in range(n):
            if self._is_available(self.keys[idx], now):
                return idx
            idx = self._advance(idx)
        best_idx, best_score = None, None
        for i, k in enumerate(self.keys):
            if k["disabled"]:
                continue
            wait = 0.0
            if k["cooldown_until"] > now:
                wait = k["cooldown_until"] - now
            else:
                self._purge_windows(k, now)
                if self._rpm(k, now) >= self.rpm_rotate_at and k["req_times"]:
                    wait = max(wait, max(0.0, 60.0 - (now - k["req_times"][0])) + 0.05)
                if self._tpm(k, now) >= self.tpm_rotate_at and k["tok_events"]:
                    wait = max(wait, max(0.0, 60.0 - (now - k["tok_events"][0][0])) + 0.05)
                if self._rpd(k, now) >= self.rpd_rotate_at:
                    tomorrow = datetime.now().replace(
                        hour=0, minute=0, second=0, microsecond=0
                    ) + timedelta(days=1)
                    wait = max(wait, (tomorrow - datetime.now()).total_seconds())
            score = (wait, k["total_requests"], i)
            if best_score is None or score < best_score:
                best_score = score
                best_idx = i
        if best_idx is None:
            return self.current_idx
        wait_needed = best_score[0]
        if wait_needed > 0.05:
            print(
                f"  {C.YELLOW}[{self.provider}] All keys at soft limit. "
                f"Waiting {wait_needed:.1f}s then using {self._label(self.keys[best_idx])}...{C.RESET}"
            )
            time.sleep(min(wait_needed, 120.0))
        return best_idx

    def _label(self, k: dict) -> str:
        uid = _mask_user_id(k.get("user_id") or "")
        short = (k["key"][:8] + "…") if len(k["key"]) > 10 else "***"
        return f"#{k['slot']} ({uid}) [{short}]"

    def get_key(self) -> str:
        with self._lock:
            now = time.time()
            prev_idx = self.current_idx
            idx = self._pick_index(now)
            if idx != prev_idx:
                old, new = self.keys[prev_idx], self.keys[idx]
                reason = self._reason_unavailable(old, now) if not self._is_available(old, now) else "round-robin"
                print(
                    f"  {C.MAGENTA}[{self.provider}] Key rotate: "
                    f"{self._label(old)} → {self._label(new)} "
                    f"(reason: {reason}){C.RESET}"
                )
                self._apply_key_switch_delay(old["slot"], new["slot"], reason)
            self.current_idx = idx
            self._last_switched_from = prev_idx
            return self.keys[idx]["key"]

    def current_label(self) -> str:
        with self._lock:
            return self._label(self.keys[self.current_idx])

    def record_success(self, tokens_est: int = 0):
        with self._lock:
            now = time.time()
            k = self.keys[self.current_idx]
            self._purge_windows(k, now)
            k["req_times"].append(now)
            k["day_count"] += 1
            k["total_requests"] += 1
            tok = max(0, int(tokens_est or 0))
            if tok:
                k["tok_events"].append((now, tok))
                k["total_tokens_est"] += tok
            if (
                self._rpm(k, now) >= self.rpm_rotate_at
                or self._rpd(k, now) >= self.rpd_rotate_at
                or self._tpm(k, now) >= self.tpm_rotate_at
            ):
                nxt = self._advance(self.current_idx)
                old_slot = k["slot"]
                print(
                    f"  {C.CYAN}[{self.provider}] Soft limit on {self._label(k)} "
                    f"→ next key #{self.keys[nxt]['slot']}{C.RESET}"
                )
                self._apply_key_switch_delay(old_slot, self.keys[nxt]["slot"], "soft limit")
                self.current_idx = nxt
                self._last_switched_from = self.current_idx

    def record_rate_limit(self, retry_after: Optional[float] = None):
        with self._lock:
            now = time.time()
            k = self.keys[self.current_idx]
            wait = float(retry_after) if retry_after and retry_after > 0 else 60.0
            wait = wait + random.uniform(0.1, 1.0)
            k["cooldown_until"] = now + wait
            k["last_error"] = f"429 cooldown {wait:.1f}s"
            old_slot = k["slot"]
            print(
                f"  {C.YELLOW}[{self.provider}] 429 on {self._label(k)} — "
                f"cooldown {wait:.1f}s, rotating...{C.RESET}"
            )
            nxt = self._advance(self.current_idx)
            self._apply_key_switch_delay(old_slot, self.keys[nxt]["slot"], "429 rate limit")
            self.current_idx = nxt

    def record_auth_error(self):
        with self._lock:
            k = self.keys[self.current_idx]
            k["disabled"] = True
            k["last_error"] = "auth 401/403"
            old_slot = k["slot"]
            print(
                f"  {C.RED}[{self.provider}] Auth failed on {self._label(k)} — "
                f"disabled for this run, rotating...{C.RESET}"
            )
            log_error(f"{self.provider} auth fail key slot #{k['slot']} user={_mask_user_id(k.get('user_id') or '')}")
            nxt = self._advance(self.current_idx)
            self._apply_key_switch_delay(old_slot, self.keys[nxt]["slot"], "auth error")
            self.current_idx = nxt

    def get_client(self) -> OpenAI:
        key = self.get_key()
        with self._lock:
            cli = self._clients.get(key)
            if cli is None:
                cli = OpenAI(base_url="https://api.groq.com/openai/v1", api_key=key)
                self._clients[key] = cli
            return cli

    def status_summary(self) -> str:
        with self._lock:
            now = time.time()
            lines = [f"  {self.provider} keys: {len(self.keys)} | active → {self._label(self.keys[self.current_idx])}"]
            for k in self.keys:
                st = "OK"
                if k["disabled"]:
                    st = "DISABLED"
                elif k["cooldown_until"] > now:
                    st = f"COOL {k['cooldown_until'] - now:.0f}s"
                elif not self._is_available(k, now):
                    st = "SOFT-LIMIT"
                lines.append(
                    f"    #{k['slot']:>2} {_mask_user_id(k.get('user_id') or '-'):<28} "
                    f"req={k['total_requests']:<5} "
                    f"RPM={self._rpm(k, now):<3} RPD={self._rpd(k, now):<6} "
                    f"[{st}]"
                )
            return "\n".join(lines)

    def balance_plain(self) -> str:
        with self._lock:
            now = time.time()
            lines = []
            for k in self.keys:
                rpm = self._rpm(k, now)
                rpd = self._rpd(k, now)
                rpm_left = max(0, self.rpm_rotate_at - rpm)
                rpd_left = max(0, self.rpd_rotate_at - rpd)
                if k["disabled"]:
                    st = "DISABLED"
                elif k["cooldown_until"] > now:
                    st = f"COOLDOWN {int(k['cooldown_until'] - now)}s"
                else:
                    st = "active"
                lines.append(
                    f"  Key #{k['slot']} ({_mask_user_id(k.get('user_id') or '')}): "
                    f"RPM {rpm}/{self.rpm_limit} (left~{rpm_left}) | "
                    f"RPD {rpd}/{self.rpd_limit} (left~{rpd_left}) | {st}"
                )
            return "\n".join(lines)


def estimate_tokens_from_text(*parts: str) -> int:
    total_chars = sum(len(str(p)) for p in parts if p)
    return max(1, total_chars // 4)


def estimate_tokens_from_response(resp) -> int:
    try:
        u = getattr(resp, "usage", None)
        if u is not None:
            pt = getattr(u, "prompt_tokens", None) or getattr(u, "input_tokens", 0) or 0
            ct = getattr(u, "completion_tokens", None) or getattr(u, "output_tokens", 0) or 0
            tt = getattr(u, "total_tokens", None)
            if tt:
                return int(tt)
            return int(pt) + int(ct)
    except Exception:
        pass
    return 0


def chat_completions_create(client: OpenAI, **kwargs):
    kwargs = dict(kwargs)
    if "max_tokens" in kwargs and "max_completion_tokens" not in kwargs:
        kwargs["max_completion_tokens"] = kwargs.pop("max_tokens")

    def _call(kw):
        return client.chat.completions.create(**kw)

    try:
        return _call(kwargs)
    except TypeError:
        if "max_completion_tokens" in kwargs:
            kw2 = dict(kwargs)
            kw2["max_tokens"] = kw2.pop("max_completion_tokens")
            try:
                return _call(kw2)
            except Exception:
                pass
        raise
    except Exception as e:
        msg = str(e).lower()
        if "response_format" in kwargs and (
            "response_format" in msg or "json_object" in msg or "unsupported" in msg
        ):
            kw2 = dict(kwargs)
            kw2.pop("response_format", None)
            return _call(kw2)
        if "max_completion_tokens" in msg or "max_tokens" in msg:
            kw2 = dict(kwargs)
            if "max_completion_tokens" in kw2:
                kw2["max_tokens"] = kw2.pop("max_completion_tokens")
                try:
                    return _call(kw2)
                except Exception as e2:
                    if "response_format" in kw2:
                        kw2.pop("response_format", None)
                        return _call(kw2)
                    raise e2
        raise


def call_with_key_rotation(
    operation_name: str,
    fn: Callable[[OpenAI], Any],
    tokens_hint: int = 0,
    max_attempts: int = None,
) -> Any:
    global GROQ_KEY_MANAGER
    if GROQ_KEY_MANAGER is None:
        raise RuntimeError("GROQ_KEY_MANAGER not initialized")
    n_keys = max(1, len(GROQ_KEY_MANAGER.keys))
    if max_attempts is None:
        max_attempts = max(6, n_keys * 2)
    last_err = None
    for attempt in range(max_attempts):
        client = GROQ_KEY_MANAGER.get_client()
        try:
            result = fn(client)
            tok = estimate_tokens_from_response(result) or tokens_hint
            GROQ_KEY_MANAGER.record_success(tokens_est=tok)
            return result
        except Exception as e:
            last_err = e
            msg = str(e).lower()
            status = None
            for attr in ("status_code", "status"):
                if hasattr(e, attr):
                    try:
                        status = int(getattr(e, attr))
                    except Exception:
                        pass
            resp_obj = getattr(e, "response", None)
            if status is None and resp_obj is not None:
                try:
                    status = int(getattr(resp_obj, "status_code", 0) or 0)
                except Exception:
                    pass
            if is_model_not_found_error(e):
                log_error(f"{operation_name} model_not_found: {e}")
                raise
            is_429 = status == 429 or "429" in msg or "rate limit" in msg or "too many requests" in msg
            is_auth = (
                status in (401, 403)
                or "invalid api key" in msg
                or "authentication" in msg
                or "unauthorized" in msg
            )
            is_5xx = (status is not None and status >= 500) or "server error" in msg
            retry_after = None
            if resp_obj is not None:
                try:
                    headers = getattr(resp_obj, "headers", None) or {}
                    if hasattr(headers, "get"):
                        ra = headers.get("retry-after") or headers.get("Retry-After")
                        if ra is not None:
                            retry_after = float(ra)
                except Exception:
                    pass
            if is_auth:
                GROQ_KEY_MANAGER.record_auth_error()
                log_error(f"{operation_name} auth: {e}")
                continue
            if is_429:
                GROQ_KEY_MANAGER.record_rate_limit(retry_after=retry_after)
                time.sleep(0.3 + random.uniform(0, 0.4))
                log_error(f"{operation_name} 429: {e}")
                continue
            if is_5xx:
                wait = min(30.0, (2 ** min(attempt, 4)) + random.uniform(0, 1))
                print(
                    f"  {C.YELLOW}[{operation_name}] server error, retry in {wait:.1f}s "
                    f"(attempt {attempt + 1}/{max_attempts}){C.RESET}"
                )
                time.sleep(wait)
                log_error(f"{operation_name} 5xx: {e}")
                continue
            log_error(f"{operation_name}: {e}")
            raise
    raise Exception(f"{operation_name} failed after {max_attempts} attempts: {last_err}")


def call_with_model_fallback(
    operation_name: str,
    model_key: str,
    make_fn: Callable[[str], Callable[[OpenAI], Any]],
    tokens_hint: int = 0,
) -> Any:
    last_err = None
    chain = model_chain(model_key)
    if not chain:
        raise RuntimeError(f"No models configured for '{model_key}'")
    print(f"            {C.DIM}model chain: {' → '.join(chain)}{C.RESET}")
    for model_id in chain:
        try:
            print(f"            {C.DIM}trying model: {model_id}{C.RESET}")
            fn = make_fn(model_id)
            return call_with_key_rotation(operation_name, fn, tokens_hint=tokens_hint)
        except Exception as e:
            last_err = e
            err_s = str(e)
            print(f"            {C.YELLOW}model fail: {model_id} → {err_s[:220]}{C.RESET}")
            if is_model_not_found_error(e):
                mark_model_dead(model_id, e)
                continue
            low = err_s.lower()
            if any(x in low for x in ("image", "vision", "multimodal", "content part")):
                mark_model_dead(model_id, e)
                continue
            raise
    raise Exception(f"{operation_name}: all models failed for '{model_key}': {last_err}")


def refresh_live_models_from_groq():
    global _LIVE_MODEL_IDS
    if GROQ_KEY_MANAGER is None:
        return
    try:
        client = GROQ_KEY_MANAGER.get_client()
        try:
            models_page = client.models.list()
            ids = []
            data = getattr(models_page, "data", None) or models_page
            for m in data:
                mid = getattr(m, "id", None) or (m.get("id") if isinstance(m, dict) else None)
                if mid:
                    ids.append(mid)
        except Exception:
            key = GROQ_KEY_MANAGER.get_key()
            req = urllib.request.Request(
                "https://api.groq.com/openai/v1/models",
                headers={"Authorization": f"Bearer {key}", "User-Agent": "UltimateMediaTool/0.9"},
            )
            with urllib.request.urlopen(req, timeout=30) as resp:
                payload = json.loads(resp.read().decode("utf-8", errors="replace"))
            ids = [m.get("id") for m in (payload.get("data") or []) if m.get("id")]

        _LIVE_MODEL_IDS = set(ids)
        try:
            GROQ_KEY_MANAGER.record_success(tokens_est=10)
        except Exception:
            pass

        print(f"  {C.GREEN}[OK] Groq live models: {len(_LIVE_MODEL_IDS)}{C.RESET}")

        preferred_vision = ["qwen/qwen3.6-27b"]
        live_vision = [m for m in preferred_vision if m in _LIVE_MODEL_IDS]
        for m in sorted(_LIVE_MODEL_IDS):
            low = m.lower()
            if m in live_vision:
                continue
            if "qwen3.6" in low or "vision" in low:
                live_vision.append(m)

        if live_vision:
            GROQ_MODELS["vision"] = live_vision[0]
            GROQ_MODELS["vision_fallbacks"] = live_vision[1:]
            print(f"  {C.GREEN}[OK] Vision primary: {GROQ_MODELS['vision']}{C.RESET}")
            if GROQ_MODELS["vision_fallbacks"]:
                print(f"  {C.DIM}     fallbacks: {', '.join(GROQ_MODELS['vision_fallbacks'][:5])}{C.RESET}")
        else:
            print(f"  {C.YELLOW}[WARN] No vision model in live catalog — keeping qwen/qwen3.6-27b{C.RESET}")
            print(f"  {C.DIM}  sample: {', '.join(sorted(_LIVE_MODEL_IDS)[:15])}{C.RESET}")
            GROQ_MODELS["vision"] = "qwen/qwen3.6-27b"

        pref_tr = [
            "llama-3.3-70b-versatile",
            "openai/gpt-oss-20b",
            "openai/gpt-oss-120b",
            "llama-3.1-8b-instant",
            "qwen/qwen3.6-27b",
        ]
        live_tr = [m for m in pref_tr if m in _LIVE_MODEL_IDS]
        if not live_tr:
            live_tr = [
                m for m in sorted(_LIVE_MODEL_IDS)
                if "whisper" not in m.lower() and "tts" not in m.lower() and "guard" not in m.lower()
            ][:6]
        if live_tr:
            GROQ_MODELS["translate"] = live_tr[0]
            GROQ_MODELS["translate_fallbacks"] = live_tr[1:]
            print(f"  {C.GREEN}[OK] Translate primary: {GROQ_MODELS['translate']}{C.RESET}")

        pref_w = ["whisper-large-v3", "whisper-large-v3-turbo"]
        live_w = [m for m in pref_w if m in _LIVE_MODEL_IDS]
        if live_w:
            GROQ_MODELS["whisper"] = live_w[0]
            GROQ_MODELS["whisper_fallbacks"] = live_w[1:]
            print(f"  {C.GREEN}[OK] Whisper primary: {GROQ_MODELS['whisper']}{C.RESET}")

    except Exception as e:
        log_error(f"models.list: {e}")
        print(f"  {C.YELLOW}[WARN] Could not list Groq models: {e}{C.RESET}")
        print(f"  {C.DIM}Using hardcoded GROQ_MODELS (vision=qwen/qwen3.6-27b){C.RESET}")


def _download_file(url: str, dest: Path, timeout: int = 120) -> None:
    req = urllib.request.Request(
        url, headers={"User-Agent": "Mozilla/5.0 (UltimateMediaTool/0.9)"}
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp, open(dest, "wb") as outf:
        shutil.copyfileobj(resp, outf)


def setup_tools():
    TOOLS_DIR.mkdir(parents=True, exist_ok=True)
    if not YTDLP_PATH.exists() or YTDLP_PATH.stat().st_size < 100_000:
        print(f"  {C.YELLOW}Downloading yt-dlp.exe ({YTDLP_RELEASE_TAG}) -> library Tools...{C.RESET}")
        try:
            _download_file(YTDLP_DOWNLOAD_URL, YTDLP_PATH)
            if not (YTDLP_PATH.exists() and YTDLP_PATH.stat().st_size > 100_000):
                _download_file(
                    "https://github.com/yt-dlp/yt-dlp/releases/latest/download/yt-dlp.exe",
                    YTDLP_PATH,
                )
            print(f"  {C.GREEN}[OK] {YTDLP_PATH}{C.RESET}\n")
        except Exception as e:
            log_error(f"yt-dlp: {e}")
            print(f"  {C.RED}yt-dlp failed: {e}{C.RESET}\n")
    else:
        print(f"  {C.GREEN}[OK] yt-dlp already present{C.RESET}")

    if not FFMPEG_PATH.exists():
        print(f"  {C.YELLOW}Downloading ffmpeg.exe -> library Tools...{C.RESET}")
        urls = [
            "https://www.gyan.dev/ffmpeg/builds/ffmpeg-release-essentials.zip",
            "https://github.com/BtbN/FFmpeg-Builds/releases/download/latest/ffmpeg-master-latest-win64-gpl.zip",
        ]
        zip_path = TOOLS_DIR / "ffmpeg.zip"
        downloaded, last_err = False, None
        for url in urls:
            try:
                print(f"  {C.DIM}Trying: {url}{C.RESET}")
                if zip_path.exists():
                    zip_path.unlink(missing_ok=True)
                _download_file(url, zip_path, timeout=300)
                if zip_path.exists() and zip_path.stat().st_size > 1_000_000:
                    downloaded = True
                    print(f"  {C.GREEN}Download OK{C.RESET}")
                    break
            except Exception as e:
                last_err = e
                print(f"  {C.YELLOW}  failed: {e}{C.RESET}")
        if not downloaded:
            log_error(f"ffmpeg: {last_err}")
            print(f"  {C.RED}ffmpeg failed: {last_err}{C.RESET}")
            print(f"  Put ffmpeg.exe manually in: {TOOLS_DIR}\n")
            return
        try:
            print(f"  {C.DIM}Extracting...{C.RESET}")
            with zipfile.ZipFile(zip_path, "r") as zf:
                zf.extractall(TOOLS_DIR)
            found_ffmpeg = found_ffprobe = False
            for root, dirs, files in os.walk(TOOLS_DIR):
                if "ffmpeg.exe" in files and not found_ffmpeg:
                    src = Path(root) / "ffmpeg.exe"
                    if src.resolve() != FFMPEG_PATH.resolve():
                        if FFMPEG_PATH.exists():
                            FFMPEG_PATH.unlink()
                        shutil.move(str(src), str(FFMPEG_PATH))
                    found_ffmpeg = True
                if "ffprobe.exe" in files and not found_ffprobe:
                    src = Path(root) / "ffprobe.exe"
                    dest_probe = TOOLS_DIR / "ffprobe.exe"
                    if src.resolve() != dest_probe.resolve():
                        if dest_probe.exists():
                            dest_probe.unlink()
                        shutil.move(str(src), str(dest_probe))
                    found_ffprobe = True
            zip_path.unlink(missing_ok=True)
            for item in list(TOOLS_DIR.iterdir()):
                if item.is_dir():
                    shutil.rmtree(item, ignore_errors=True)
            if found_ffmpeg and FFMPEG_PATH.exists():
                print(f"  {C.GREEN}[OK] {FFMPEG_PATH}{C.RESET}")
                if found_ffprobe:
                    print(f"  {C.GREEN}[OK] ffprobe.exe extracted{C.RESET}")
                print()
            else:
                print(f"  {C.RED}ffmpeg.exe not found after extract{C.RESET}\n")
        except Exception as e:
            log_error(f"ffmpeg extract: {e}")
            print(f"  {C.RED}ffmpeg extract failed: {e}{C.RESET}\n")
    else:
        print(f"  {C.GREEN}[OK] ffmpeg already present{C.RESET}")


# ====
# GOOGLE DRIVE SHARED FOLDER SOURCE
# ====
def _safe_folder_component(name: str, fallback: str = "Google Drive") -> str:
    """Make a Google Doc title safe as a Windows folder/file stem."""
    name = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", str(name or "")).strip().rstrip(".")
    name = re.sub(r"\s+", " ", name)
    return name[:150] or fallback


def _drive_root_folder(doc_title: str) -> Path:
    return MEDIA_DIR / _safe_folder_component(doc_title)


def _drive_done_file(doc_title: str) -> Path:
    return _drive_root_folder(doc_title) / f"Completed {_safe_folder_component(doc_title)} URL.txt"


def _drive_failed_file(doc_title: str) -> Path:
    return _drive_root_folder(doc_title) / f"Failed {_safe_folder_component(doc_title)} URL.txt"


def _archive_drive_failed_url(doc_title: str, url: str, reason: str = "") -> None:
    """Record a permanent Drive-URL failure so it is not retried forever."""
    try:
        path = _drive_failed_file(doc_title)
        path.parent.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        line = f"{stamp}\t{url}"
        if reason:
            compact = " ".join(str(reason).split())
            line += f"\t# {compact[:240]}"
        line += "\n"
        with open(path, "a", encoding="utf-8") as f:
            f.write(line)
        print_step("~", f"Permanent failure recorded → {path.name}", C.YELLOW)
    except Exception as e:
        log_error(f"drive failed write [{doc_title}]: {e}")


def _load_drive_failed_urls(doc_title: str) -> set:
    path = _drive_failed_file(doc_title)
    failed = set()
    try:
        if not path.exists():
            return failed
        text = path.read_text(encoding="utf-8", errors="replace")
        for line in text.splitlines():
            m = re.search(r"https?://[^\s<>\"\'\]\)\}]+", line, re.IGNORECASE)
            if m:
                failed.add(m.group(0).rstrip(".,;:)").lower())
    except Exception as e:
        log_error(f"drive failed read [{doc_title}]: {e}")
    return failed


def _drive_log_files(doc_title: str) -> dict:
    """Only the two media logs required for Google-Doc jobs."""
    root = _drive_root_folder(doc_title)
    stem = _safe_folder_component(doc_title)
    return {
        "Image": root / f"{stem} Image Scraper.txt",
        "Video": root / f"{stem} Video Scraper.txt",
    }


def _drive_media_folders(doc_title: str) -> dict:
    """Only Image and Video folders. Audio files are deliberately stored in Video."""
    root = _drive_root_folder(doc_title)
    stem = _safe_folder_component(doc_title)
    return {
        "Image": root / f"{stem} Image Scraper",
        "Video": root / f"{stem} Video Scraper",
    }


def _read_urls_from_text(text: str) -> List[str]:
    urls, seen = [], set()
    for m in re.finditer(r"https?://[^\s<>\"'\])\}]+", text or "", re.IGNORECASE):
        u = m.group(0).rstrip(".,;:)")
        if not u or u.lower() in seen:
            continue
        seen.add(u.lower())
        urls.append(u)
    return urls


def _load_drive_done_urls(doc_title: str) -> set:
    path = _drive_done_file(doc_title)
    done = set()
    try:
        if not path.exists():
            return done
        text = path.read_text(encoding="utf-8", errors="replace")
        for line in text.splitlines():
            m = re.search(r"https?://[^\s<>\"'\])\}]+", line, re.IGNORECASE)
            if m:
                done.add(m.group(0).rstrip(".,;:)").lower())
    except Exception as e:
        log_error(f"drive done read [{doc_title}]: {e}")
    return done


def _archive_drive_completed_url(doc_title: str, url: str, note: str = "") -> None:
    """Newest completed URL first; oldest is #1 and newest gets largest serial."""
    try:
        path = _drive_done_file(doc_title)
        path.parent.mkdir(parents=True, exist_ok=True)

        existing = []
        if path.exists():
            old_text = path.read_text(encoding="utf-8", errors="replace")
            for line in old_text.splitlines():
                m = re.search(r"https?://[^\s<>\"'\])\}]+", line, re.IGNORECASE)
                if m:
                    u = m.group(0).rstrip(".,;:)")
                    if u.lower() not in {x.lower() for x in existing}:
                        existing.append(u)

        if url.lower() not in {x.lower() for x in existing}:
            existing.append(url)

        total = len(existing)
        lines = [f"{total - i}. {u}" for i, u in enumerate(reversed(existing))]
        path.write_text("\n".join(lines) + "\n", encoding="utf-8")
        print_step("+", f"Recorded in {path.name}", C.GREEN)
    except Exception as e:
        log_error(f"drive done write [{doc_title}]: {e}")


def _google_credentials_path() -> Path:
    candidates = [
        MEDIA_DIR / "credentials.json",
        Path(LIB_ROOT) / "credentials.json",
        Path("credentials.json"),
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return candidates[0]


def _google_token_path() -> Path:
    return MEDIA_DIR / "token.json"


def _google_token_has_required_scopes(creds) -> bool:
    try:
        scopes = set(getattr(creds, "scopes", None) or getattr(creds, "granted_scopes", None) or [])
        required = set(GOOGLE_DRIVE_SCOPES)
        return required.issubset(scopes)
    except Exception:
        return False


def _get_google_drive_service():
    if not GOOGLE_DRIVE_ENABLED:
        return None
    if not HAS_GOOGLE_APIS:
        raise RuntimeError(
            "Google API libraries are unavailable. "
            f"Verified GoogleLibs: {GOOGLE_LIBS}"
        )
    credentials_path = _google_credentials_path()
    token_path = _google_token_path()
    creds = None

    if token_path.exists():
        try:
            creds = GoogleCredentials.from_authorized_user_file(
                str(token_path), GOOGLE_DRIVE_SCOPES
            )
        except Exception:
            creds = None

    # A token issued previously with drive.readonly cannot silently gain
    # documents write permission. Re-authorize only when the required scope
    # is actually missing.
    if creds and not _google_token_has_required_scopes(creds):
        print("  [DRIVE] Existing token lacks Google Docs edit permission; reauthorization required.")
        # Keep the old token as a backup, then force a fresh consent flow.
        try:
            backup = token_path.with_name("token_old_scope.json")
            if backup.exists():
                backup.unlink()
            token_path.replace(backup)
            print_step("!", f"Old OAuth token moved to {backup.name}", C.YELLOW)
        except Exception as e:
            print_step("!", f"Could not back up old OAuth token: {e}", C.YELLOW)
        creds = None

    if not creds or not creds.valid:
        if creds and creds.expired and creds.refresh_token:
            try:
                creds.refresh(GoogleAuthRequest())
            except Exception:
                creds = None

        if not creds or not creds.valid:
            if not credentials_path.exists():
                raise FileNotFoundError(
                    f"Google credentials.json not found. Place it here: {credentials_path}"
                )
            print(f"\n  {C.CYAN}{C.BOLD}Google Drive/Docs authorization required{C.RESET}")
            print("  Google will open its sign-in page in your browser.")
            flow = InstalledAppFlow.from_client_secrets_file(
                str(credentials_path), GOOGLE_DRIVE_SCOPES
            )
            creds = flow.run_local_server(port=0, open_browser=True)

        token_path.write_text(creds.to_json(), encoding="utf-8")
        print_step("+", f"Google OAuth token saved → {token_path.name}", C.GREEN)

    return google_build("drive", "v3", credentials=creds, cache_discovery=False)


def _get_google_docs_service():
    if not HAS_GOOGLE_APIS:
        raise RuntimeError(f"Google API imports unavailable. Check {GOOGLE_LIBS}")
    drive_service = _get_google_drive_service()
    # Reuse the same authorized credentials stored in token.json.
    token_path = _google_token_path()
    creds = GoogleCredentials.from_authorized_user_file(
        str(token_path), GOOGLE_DRIVE_SCOPES
    )
    return google_build("docs", "v1", credentials=creds, cache_discovery=False)


def _collect_doc_text_runs(elements, output):
    """Collect (text, startIndex, endIndex) from Google Docs structural elements."""
    for element in elements or []:
        if "paragraph" in element:
            for pe in element["paragraph"].get("elements", []):
                tr = pe.get("textRun")
                if tr and tr.get("content"):
                    output.append((
                        tr["content"],
                        int(pe.get("startIndex", 0)),
                        int(pe.get("endIndex", 0)),
                    ))
        elif "table" in element:
            for row in element["table"].get("tableRows", []):
                for cell in row.get("tableCells", []):
                    _collect_doc_text_runs(cell.get("content", []), output)
        elif "tableOfContents" in element:
            _collect_doc_text_runs(
                element["tableOfContents"].get("content", []), output
            )


def _remove_url_from_google_doc(file_id: str, url: str) -> bool:
    """Remove every exact URL occurrence from a Google Doc after successful processing."""
    try:
        docs_service = _get_google_docs_service()
        document = docs_service.documents().get(documentId=file_id).execute()
        runs = []
        _collect_doc_text_runs(document.get("body", {}).get("content", []), runs)
        target = (url or "").strip()
        if not target or not runs:
            return False

        # Build a character-by-character map to REAL Google Docs indices.
        # This works even when a URL is split across multiple styled textRuns.
        chars = []
        for content, start_idx, end_idx in runs:
            for off, ch in enumerate(content):
                chars.append((ch, int(start_idx) + off))
        full_text = "".join(ch for ch, _ in chars)

        matches = []
        pos = 0
        while True:
            i = full_text.find(target, pos)
            if i < 0:
                break
            matches.append((i, i + len(target)))
            pos = i + len(target)
        if not matches:
            m = re.search(re.escape(target), full_text, re.IGNORECASE)
            if m:
                matches = [(m.start(), m.end())]
        if not matches:
            print_step("!", "Completed URL was not found in source Google Doc", C.YELLOW)
            return False

        requests = []
        for a, b in reversed(matches):
            if a >= len(chars) or b <= a:
                continue
            doc_a = chars[a][1]
            doc_b_exclusive = chars[b - 1][1] + 1
            if doc_b_exclusive <= doc_a:
                continue
            requests.append({
                "deleteContentRange": {
                    "range": {
                        "startIndex": int(doc_a),
                        "endIndex": int(doc_b_exclusive),
                    }
                }
            })

        if not requests:
            return False
        docs_service.documents().batchUpdate(
            documentId=file_id, body={"requests": requests}
        ).execute()

        # Verify the URL is really gone before reporting success. This prevents
        # a local "Completed" archive when Google Docs rejected/partially applied
        # the deletion.
        verify = docs_service.documents().get(documentId=file_id).execute()
        verify_runs = []
        _collect_doc_text_runs(verify.get("body", {}).get("content", []), verify_runs)
        verify_text = "".join(content for content, _, _ in verify_runs)
        if target.lower() in verify_text.lower():
            print_step("!", "Google Docs update completed but URL is still present; not archiving it.", C.YELLOW)
            return False

        print_step("+", f"Removed completed URL from Google Doc: {url}", C.GREEN)
        return True
    except Exception as e:
        log_error(f"Google Doc URL removal [{file_id}]: {url}\n{traceback.format_exc()}")
        print_step("!", f"Could not remove URL from Google Doc: {e}", C.RED)
        return False

def _export_google_doc_text(service, file_id: str) -> str:
    data = service.files().export(fileId=file_id, mimeType="text/plain").execute()
    return data.decode("utf-8", errors="replace") if isinstance(data, bytes) else str(data or "")


def _list_google_drive_docs() -> Tuple[bool, List[Tuple[str, str]]]:
    """Return [(Drive file ID, Google Doc title)] from the configured folder."""
    if not GOOGLE_DRIVE_ENABLED:
        return True, []
    try:
        service = _get_google_drive_service()
        query = (
            f"'{GOOGLE_DRIVE_FOLDER_ID}' in parents and trashed = false "
            f"and mimeType = 'application/vnd.google-apps.document'"
        )
        docs = []
        page_token = None
        print(f"\n  {C.CYAN}{C.BOLD}[DRIVE] Scanning configured folder for Google Docs...{C.RESET}")
        while True:
            kwargs = {
                "q": query,
                "spaces": "drive",
                "pageSize": 1000,
                "fields": "nextPageToken,files(id,name,mimeType,modifiedTime)",
                "includeItemsFromAllDrives": True,
                "supportsAllDrives": True,
            }
            if page_token:
                kwargs["pageToken"] = page_token
            response = service.files().list(**kwargs).execute()
            for item in response.get("files", []):
                docs.append((item["id"], item.get("name") or "Untitled"))
            page_token = response.get("nextPageToken")
            if not page_token:
                break
        docs.sort(key=lambda x: x[1].lower())
        print_step("+", f"[DRIVE] Found {len(docs)} Google Doc(s) in shared folder", C.GREEN)
        for _, title in docs:
            print(f"      {C.DIM}• {title}{C.RESET}")
        return True, docs
    except Exception as e:
        log_error(f"Google Drive folder scan: {e}\n{traceback.format_exc()}")
        print_step("!", f"Google Drive scan failed: {e}", C.RED)
        return False, []


def _download_google_doc_text(file_id: str, doc_title: str) -> Optional[str]:
    try:
        service = _get_google_drive_service()
        return _export_google_doc_text(service, file_id)
    except Exception as e:
        log_error(f"Google Doc read [{doc_title}]: {e}\n{traceback.format_exc()}")
        print_step("!", f"Could not read Google Doc '{doc_title}': {e}", C.RED)
        return None


def _ensure_google_doc_outputs(doc_title: str) -> None:
    """Create the per-Google-Doc output folders/logs without touching the master picker."""
    root = _drive_root_folder(doc_title)
    root.mkdir(parents=True, exist_ok=True)
    folders = _drive_media_folders(doc_title)
    logs = _drive_log_files(doc_title)
    for folder in folders.values():
        folder.mkdir(parents=True, exist_ok=True)
    for log_path in logs.values():
        if not log_path.exists():
            log_path.write_text("", encoding="utf-8-sig")


def _process_google_drive_docs() -> Tuple[bool, bool]:
    global _ACTIVE_SOURCE_URL
    """Process Drive Docs first. Returns (scan_ok, had_unprocessed_url)."""
    scan_ok, docs = _list_google_drive_docs()
    if not scan_ok:
        return False, False
    if not docs:
        return True, False

    any_unprocessed_url = False
    for file_id, doc_title in docs:
        _ensure_google_doc_outputs(doc_title)
        print(f"\n  {C.CYAN}{C.BOLD}Google Doc: {doc_title}{C.RESET}")
        text = _download_google_doc_text(file_id, doc_title)
        if text is None:
            any_unprocessed_url = True
            continue
        all_urls = _read_urls_from_text(text)
        done = _load_drive_done_urls(doc_title)
        failed = _load_drive_failed_urls(doc_title)
        skip = done | failed
        urls = [u for u in all_urls if u.lower() not in skip]
        if not urls:
            print_step("~", f"No new/unprocessed URLs in '{doc_title}'", C.DIM)
            continue
        any_unprocessed_url = True
        print_step("+", f"Found {len(urls)} unprocessed URL(s) in '{doc_title}'", C.GREEN)
        for i, url in enumerate(urls, start=1):
            print(f"  {C.BOLD}[{doc_title} URL {i}/{len(urls)}] {url}{C.RESET}")
            work = _drive_root_folder(doc_title) / ".AKT Drive Work"
            try:
                work.mkdir(parents=True, exist_ok=True)
                saved_list, dl_log, permanent = download_media_from_url(url, work)
                if not saved_list:
                    if permanent:
                        print_step(
                            "!",
                            "Permanent download failure — removing from Google Doc (no infinite retry)",
                            C.RED,
                        )
                        if _remove_url_from_google_doc(file_id, url):
                            _archive_drive_failed_url(doc_title, url, reason=dl_log)
                        else:
                            print_step(
                                "!",
                                "Could not remove permanent-fail URL from Doc; left for a later retry",
                                C.YELLOW,
                            )
                    else:
                        print_step("!", "Download failed — URL remains unprocessed for retry", C.YELLOW)
                    continue
                print_step("+", f"Downloaded {len(saved_list)} media file(s) from URL", C.GREEN)

                # Screenshot stage is deliberately SEPARATE from OCR/Whisper.
                # The scraper receives only saved_list (the original downloaded media),
                # so timestamped screenshots and green-screen screenshots are NEVER
                # sent to OCR/transcription.
                try:
                    screenshot_root = _drive_root_folder(doc_title) / "Screenshots"
                    screenshot_paths = run_screenshot_stage(url, screenshot_root)
                    if screenshot_paths:
                        print_step("+", f"Created {len(screenshot_paths)} timestamp/green screenshot(s) — excluded from OCR/Whisper", C.GREEN)
                except Exception as shot_err:
                    print_step("~", f"Screenshot stage skipped: {shot_err}", C.YELLOW)

                _ACTIVE_SOURCE_URL = url
                s, f = run_scraper(only_files=saved_list, output_prefix=doc_title, output_root=_drive_root_folder(doc_title), drive_doc_mode=True)
                if s > 0 and f == 0:
                    # FIRST remove the URL from the source Google Doc.
                    # Only after successful removal do we archive it locally.
                    if _remove_url_from_google_doc(file_id, url):
                        _archive_drive_completed_url(
                            doc_title, url,
                            note=f"{len(saved_list)} file(s) downloaded + scraped"
                        )
                    else:
                        print_step(
                            "!",
                            "Media job succeeded, but Google Doc URL could not be removed; "
                            "URL remains for retry.",
                            C.YELLOW,
                        )
                else:
                    print_step("!", "Scrape incomplete — URL remains unprocessed for retry", C.YELLOW)
            except Exception as e:
                print_step("!", f"Google Doc URL job failed — kept for retry: {e}", C.RED)
                log_error(f"drive doc URL job [{doc_title}]: {url}\n{traceback.format_exc()}")
            finally:
                try:
                    if work.exists():
                        shutil.rmtree(work, ignore_errors=True)
                except Exception:
                    pass
    return True, any_unprocessed_url


