def _snapshot_files(dest_folder: Path) -> Dict[str, Tuple[int, int]]:
    snap: Dict[str, Tuple[int, int]] = {}
    try:
        for p in dest_folder.rglob("*"):
            if p.is_file():
                rel = str(p.relative_to(dest_folder)).replace("\\", "/").lower()
                try:
                    st = p.stat()
                    snap[rel] = (st.st_mtime_ns, st.st_size)
                except Exception:
                    snap[rel] = (0, 0)
    except Exception:
        pass
    return snap


def _is_already_named_output(filename: str) -> bool:
    return bool(_RE_DONE_NAME.match(filename or ""))


def _is_instagram_url(url: str) -> bool:
    low = url.lower()
    return "instagram.com" in low or "instagr.am" in low


def _is_social_media_url(url: str) -> bool:
    low = url.lower()
    hosts = (
        "instagram.com", "instagr.am",
        "twitter.com", "x.com",
        "facebook.com", "fb.watch",
        "tiktok.com", "youtube.com", "youtu.be",
        "reddit.com", "pinterest.com", "threads.net",
        "vimeo.com", "dailymotion.com",
    )
    return any(h in low for h in hosts)


def _thumbnail_group_key(path: Path) -> str:
    name = path.name
    m = re.match(r"^(.*)\.(\d+)(\.[^.]+)$", name)
    if m:
        return m.group(1).lower()
    return path.stem.lower()


def _dedupe_thumbnail_variants(images: List[Path]) -> List[Path]:
    if not images:
        return []
    groups: Dict[str, List[Path]] = {}
    for p in images:
        groups.setdefault(_thumbnail_group_key(p), []).append(p)
    kept, removed = [], 0
    for key, paths in groups.items():
        if len(paths) == 1:
            kept.append(paths[0])
            continue
        paths_sorted = sorted(
            paths,
            key=lambda x: (x.stat().st_size if x.exists() else 0, x.name),
            reverse=True,
        )
        kept.append(paths_sorted[0])
        for junk in paths_sorted[1:]:
            try:
                junk.unlink(missing_ok=True)
                removed += 1
            except Exception:
                pass
    if removed:
        print_step("~", f"Kept 1 thumbnail per slide — removed {removed} lower-res variant(s)", C.CYAN)
    kept.sort(key=lambda x: x.name.lower())
    return kept


def _collect_new_media(dest_folder: Path, before_meta: Dict[str, Tuple[int, int]]) -> List[Path]:
    found: List[Path] = []
    try:
        for p in dest_folder.rglob("*"):
            if not p.is_file():
                continue
            if _is_already_named_output(p.name):
                continue
            parts_lower = [x.lower() for x in p.relative_to(dest_folder).parts]
            if any("scraper by akt" in x for x in parts_lower):
                continue
            rel = str(p.relative_to(dest_folder)).replace("\\", "/").lower()
            try:
                st = p.stat()
                meta = (st.st_mtime_ns, st.st_size)
            except Exception:
                continue
            prev = before_meta.get(rel)
            if prev is not None and prev == meta:
                continue
            if p.suffix.lower() not in ALL_EXT:
                continue
            if st.st_size < 500:
                continue
            found.append(p)
    except Exception:
        pass

    flattened: List[Path] = []
    for p in found:
        if p.parent == dest_folder:
            flattened.append(p)
            continue
        target = dest_folder / p.name
        n = 1
        while target.exists() and target.resolve() != p.resolve():
            target = dest_folder / f"{p.stem}_{n}{p.suffix}"
            n += 1
        if target.resolve() != p.resolve():
            try:
                shutil.move(str(p), str(target))
                flattened.append(target)
            except Exception:
                flattened.append(p)
        else:
            flattened.append(p)

    images = [p for p in flattened if p.suffix.lower() in IMAGE_EXT]
    others = [p for p in flattened if p.suffix.lower() not in IMAGE_EXT]
    images = _dedupe_thumbnail_variants(images)
    out = images + others
    out.sort(key=lambda x: x.name.lower())
    return out


def _gallery_dl_available() -> bool:
    """Check gallery-dl using the same real-import mechanism as startup."""
    return _package_importable("gallery_dl", SITE_PACKAGES)


BROWSERS = ["firefox", "chrome", "edge", "brave", "opera", "chromium", "vivaldi"]


def _ytdlp_bin() -> Optional[str]:
    """Prefer bundled yt-dlp.exe; fall back to python -m yt_dlp."""
    try:
        if YTDLP_PATH.exists() and YTDLP_PATH.stat().st_size > 1000:
            return str(YTDLP_PATH)
    except Exception:
        pass
    return None


def _instagram_ytdlp_base_cmd(url: str, out_tmpl: str) -> List[str]:
    """MEDIA-ONLY Instagram yt-dlp command."""
    ytdlp = _ytdlp_bin()
    if ytdlp:
        head = [ytdlp, url, "-o", out_tmpl]
    else:
        head = [sys.executable, "-m", "yt_dlp", url, "-o", out_tmpl]
    return head + [
        "--yes-playlist",
        "--no-mtime",
        "--ignore-errors",
        "--ignore-no-formats-error",
        "-f", "bv*+ba/b/best",
        "--format-sort", "res,br,size",
        "--concurrent-fragments", "8",
        "--no-warnings",
        "--no-write-info-json",
        "--no-write-thumbnail",
        "--no-write-comments",
        "--no-write-description",
        "--retries", "3",
    ]


def download_via_instagram_ytdlp(url: str, dest_folder: Path) -> Tuple[List[Path], str]:
    dest_folder.mkdir(parents=True, exist_ok=True)
    if _ytdlp_bin() is None:
        try:
            import yt_dlp  # noqa: F401
        except ImportError:
            try:
                subprocess.check_call(
                    [sys.executable, "-m", "pip", "install", "--upgrade", "--target", SITE_PACKAGES, "yt-dlp"]
                )
                importlib.invalidate_caches()
            except Exception as e:
                return [], f"yt-dlp not available: {e}"

    out_tmpl = str(
        dest_folder / "%(id)s_%(playlist_index|)s%(playlist_index&_)s%(title).80B.%(ext)s"
    )
    combined_log: List[str] = []
    env = {
        **os.environ,
        "PYTHONPATH": SITE_PACKAGES + os.pathsep + os.environ.get("PYTHONPATH", ""),
    }

    print_step("~", "Instagram cookie auth order: Firefox → Chrome → Edge → Brave → …", C.CYAN)

    def _run(cmd: List[str], label: str) -> str:
        print_step("~", f"yt-dlp Instagram [{label}]: {url[:80]}...", C.DIM)
        try:
            proc = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=600,
                cwd=str(dest_folder),
                env=env,
            )
            out = (proc.stdout or "") + "\n" + (proc.stderr or "")
            for line in out.splitlines():
                low = line.lower()
                if any(
                    x in low
                    for x in (
                        "download", "100%", "error", "destination", "writing",
                        "merging", "cookie", "extract", "warning",
                    )
                ):
                    print(f"      {C.DIM}{line.strip()[:120]}{C.RESET}")
            return out
        except subprocess.TimeoutExpired:
            return f"yt-dlp Instagram [{label}] timed out (600s)"
        except Exception as e:
            return f"yt-dlp Instagram [{label}] failed: {e}"

    for browser in BROWSERS:
        before = _snapshot_files(dest_folder)
        cmd = _instagram_ytdlp_base_cmd(url, out_tmpl) + ["--cookies-from-browser", browser]
        print_step("~", f"Trying {browser.upper()} cookies...", C.DIM)
        log = _run(cmd, f"cookies:{browser}")
        combined_log.append(f"=== cookies:{browser} ===\n{log}")
        media = _collect_new_media(dest_folder, before)
        if media:
            for p in media:
                print_step("+", f"Saved via Instagram yt-dlp ({browser}) → {p.name}", C.GREEN)
            print_step("+", f"Download finished via {browser.upper()} cookies!", C.GREEN)
            return media, "\n".join(combined_log)
        print_step("!", f"{browser} cookies produced no new media — next...", C.YELLOW)

    before = _snapshot_files(dest_folder)
    print_step("~", "Final Instagram attempt without cookies (public only)...", C.DIM)
    log = _run(_instagram_ytdlp_base_cmd(url, out_tmpl), "public")
    combined_log.append(f"=== public ===\n{log}")
    media = _collect_new_media(dest_folder, before)
    if media:
        for p in media:
            print_step("+", f"Saved via Instagram yt-dlp (public) → {p.name}", C.GREEN)
        print_step("+", "Download finished (public / no cookies)!", C.GREEN)
        return media, "\n".join(combined_log)

    print_step("!", "Instagram yt-dlp finished but no new media in folder", C.YELLOW)
    return [], "\n".join(combined_log)


def download_via_gallery_dl(url: str, dest_folder: Path) -> Tuple[List[Path], str]:
    if not _gallery_dl_available():
        return [], "gallery-dl not installed"
    dest_folder.mkdir(parents=True, exist_ok=True)
    before = _snapshot_files(dest_folder)
    cmd = [
        sys.executable, "-m", "gallery_dl",
        "--dest", str(dest_folder),
        "-f", "{id}_{num}.{extension}",
        url,
    ]
    print_step("~", f"gallery-dl: {url[:80]}...", C.DIM)
    try:
        proc = subprocess.run(
            cmd,
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=300, cwd=str(dest_folder),
            env={**os.environ, "PYTHONPATH": SITE_PACKAGES + os.pathsep + os.environ.get("PYTHONPATH", "")},
        )
        log = (proc.stdout or "") + "\n" + (proc.stderr or "")
        for line in log.splitlines():
            low = line.lower()
            if any(x in low for x in ("download", "error", "#", "http", "writing")):
                print(f"      {C.DIM}{line.strip()[:120]}{C.RESET}")
        media = _collect_new_media(dest_folder, before)
        if media:
            for p in media:
                print_step("+", f"Saved via gallery-dl → {p.name}", C.GREEN)
            return media, log
        return [], log
    except subprocess.TimeoutExpired:
        return [], "gallery-dl timed out (300s)"
    except Exception as e:
        return [], f"gallery-dl failed: {e}"


def download_via_ytdlp(url: str, dest_folder: Path) -> Tuple[List[Path], str]:
    if not YTDLP_PATH.exists():
        return [], "yt-dlp not available"
    dest_folder.mkdir(parents=True, exist_ok=True)
    before = _snapshot_files(dest_folder)
    out_tmpl = str(dest_folder / "%(id)s_%(playlist_index|)s%(playlist_index&_)s%(title).60B.%(ext)s")

    cmd_media = [
        str(YTDLP_PATH), url,
        "-o", out_tmpl,
        "--no-mtime",
        "-f", "bv*[height<=720]+ba/b[height<=720]/best",
        "--merge-output-format", "mp4",
        "--ignore-no-formats-error",
        "--write-thumbnail",
        "--convert-thumbnails", "jpg",
        "--retries", "3",
    ]
    cmd_thumbs = [
        str(YTDLP_PATH), url,
        "-o", out_tmpl,
        "--no-mtime",
        "--skip-download",
        "--ignore-no-formats-error",
        "--write-thumbnail",
        "--convert-thumbnails", "jpg",
        "--retries", "3",
    ]

    combined_log = ""

    def _run(cmd: List[str], label: str) -> str:
        print_step("~", f"yt-dlp [{label}]: {url[:80]}...", C.DIM)
        try:
            proc = subprocess.run(
                cmd, capture_output=True, text=True, encoding="utf-8",
                errors="replace", timeout=300,
            )
            out = (proc.stdout or "") + "\n" + (proc.stderr or "")
            for line in out.splitlines():
                low = line.lower()
                if any(x in low for x in ("download", "100%", "error", "destination", "writing", "merging", "thumbnail")):
                    print(f"      {C.DIM}{line.strip()[:120]}{C.RESET}")
            return out
        except subprocess.TimeoutExpired:
            return f"yt-dlp [{label}] timed out"
        except Exception as e:
            return f"yt-dlp [{label}] failed: {e}"

    combined_log += _run(cmd_media, "media+thumbs")
    media = _collect_new_media(dest_folder, before)
    if media:
        for p in media:
            print_step("+", f"Saved via yt-dlp → {p.name}", C.GREEN)
        return media, combined_log

    if _is_instagram_url(url) or "no video formats found" in combined_log.lower():
        before2 = _snapshot_files(dest_folder)
        combined_log += "\n" + _run(cmd_thumbs, "thumbs-only")
        media = _collect_new_media(dest_folder, before2)
        if media:
            for p in media:
                print_step("+", f"Saved via yt-dlp thumbnail → {p.name}", C.GREEN)
            return media, combined_log

    print_step("!", "yt-dlp finished but no new media in folder", C.YELLOW)
    return [], combined_log


def finish_url_job(url: str, saved_list: List[Path], success: bool) -> None:
    names = [p.name for p in saved_list]
    if success and saved_list:
        remove_url_from_picker(url)
        archive_completed_url(url, note=f"{len(saved_list)} file(s) downloaded + scraped")
        write_job_log(url=url, downloaded_files=names, status="OK")
    else:
        print_step("!", "Download/scrape incomplete — URL kept in picker for retry", C.YELLOW)
        write_job_log(url=url, downloaded_files=names, status="FAILED — URL kept in picker")




def _x_tweet_id(url: str) -> Optional[str]:
    """Extract a numeric X/Twitter status id from a URL when present."""
    try:
        m = re.search(r"(?:twitter\.com|x\.com)/[^/]+/status/(\d+)", url or "", re.I)
        if m:
            return m.group(1)
        m = re.search(r"status(?:es)?/(\d+)", url or "", re.I)
        return m.group(1) if m else None
    except Exception:
        return None


def _browser_fallback_page_urls(url: str, platform: str) -> List[str]:
    """
    Prefer the public X embed player first — it exposes media with far less
    login-wall friction than the full x.com page used by the screenshotter.
    """
    urls = []
    if (platform or "").lower() in ("x", "twitter"):
        tweet_id = _x_tweet_id(url)
        if tweet_id:
            urls.append(
                f"https://platform.twitter.com/embed/Tweet.html?id={tweet_id}&theme=light"
            )
            urls.append(f"https://cdn.syndication.twimg.com/tweet-result?id={tweet_id}")
    if url and url not in urls:
        urls.append(url)
    # De-dupe while preserving order
    out, seen = [], set()
    for u in urls:
        key = u.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(u)
    return out or ([url] if url else [])


async def _browser_network_video_fallback_async(
    url: str,
    dest_folder: str,
    platform: str,
    username: str,
    timestamp_str: str,
) -> List[Path]:
    """
    Last-resort browser/network fallback.

    It runs ONLY after the no-cookie yt-dlp/gallery-dl/executable methods have
    failed. It opens the real page in Playwright, optionally reuses the user's
    browser cookies, watches network traffic for video/HLS media, inspects
    <video>.currentSrc, and downloads a recovered stream. Generated screenshots
    are never used here and the returned paths are ORIGINAL media only.
    """
    from playwright.async_api import async_playwright

    dest = Path(dest_folder)
    dest.mkdir(parents=True, exist_ok=True)
    domain = (urlparse(url).hostname or "").lower()
    cookies = get_browser_cookies_for_domain(domain)
    candidates = []
    seen = set()
    response_candidates = []

    def add_candidate(u: str, kind: str = ""):
        if not u or not isinstance(u, str):
            return
        u = u.strip().strip('"').strip("'")
        if u.startswith("blob:"):
            return
        if not re.match(r"^https?://", u, re.I):
            return
        low = u.lower()
        if any(
            x in low
            for x in (
                ".m3u8", ".mpd", ".mp4", ".m4v", ".mov", ".webm", ".mkv",
                "video.twimg.com", "video.twimg", "amplify_video",
                "/ext_tw_video/", "/tweet_video/",
            )
        ):
            key = u.split("#", 1)[0]
            if key not in seen:
                seen.add(key)
                candidates.append((key, kind))

    try:
        async with async_playwright() as pw:
            browser = None
            contexts = []

            # Firefox is already installed by the tool setup.
            try:
                browser = await pw.firefox.launch(headless=True)
                print("  [+] BROWSER FALLBACK: Firefox")
            except Exception as e:
                print(f"  [i] Firefox browser fallback unavailable: {e}")

            # If Firefox cannot launch, try an installed Chromium-family browser.
            if browser is None:
                try:
                    browser = await launch_installed_chrome_family(pw)
                except Exception as e:
                    print(f"  [i] Chromium-family browser fallback unavailable: {e}")
                    return []

            try:
                context = await new_mobile_context(browser, S24_CHROME_UA, cookies)
                contexts.append(context)
                page = await context.new_page()

                async def on_response(resp):
                    try:
                        ct = (resp.headers.get("content-type") or "").lower()
                        ru = resp.url
                        if (
                            "video/" in ct
                            or "application/vnd.apple.mpegurl" in ct
                            or "application/x-mpegurl" in ct
                            or "application/dash+xml" in ct
                            or any(x in ru.lower() for x in (".m3u8", ".mpd", ".mp4", ".m4v", ".webm", ".mov"))
                            or "video.twimg.com" in ru.lower()
                        ):
                            response_candidates.append((resp, ct))
                            add_candidate(ru, ct)
                    except Exception:
                        pass

                page.on("response", on_response)

                page_urls = _browser_fallback_page_urls(url, platform)
                for page_url in page_urls:
                    print(f"  [+] BROWSER FALLBACK: opening {page_url}")
                    try:
                        await page.goto(page_url, wait_until="domcontentloaded", timeout=60000)
                    except Exception as e:
                        print(f"  [i] Browser navigation warning: {e}")
                        continue

                    # For syndication JSON, try to harvest media URLs from the body.
                    if "cdn.syndication.twimg.com/tweet-result" in page_url.lower():
                        try:
                            body_text = await page.evaluate("() => document.body && document.body.innerText || ''")
                            for m in re.finditer(r"https?://[^\s\"\']+", body_text or ""):
                                add_candidate(m.group(0).rstrip(".,);"), "syndication-json")
                        except Exception:
                            pass
                        if candidates:
                            break

                    # Give the social site's JS/video player time to initialize.
                    for delay in (2500, 4000, 5000):
                        await page.wait_for_timeout(delay)
                        try:
                            await page.evaluate(
                                """() => {
                                    window.scrollTo(0, Math.max(0, document.body.scrollHeight * 0.15));
                                    for (const v of document.querySelectorAll('video')) {
                                        try { v.muted = true; v.playsInline = true; }
                                        catch(e) {}
                                    }
                                }"""
                            )
                        except Exception:
                            pass

                        # Ask every visible video element for its actual current source.
                        try:
                            srcs = await page.evaluate(
                                """() => Array.from(document.querySelectorAll('video'))
                                    .map(v => v.currentSrc || v.src || '')
                                    .filter(Boolean)"""
                            )
                            for src in srcs or []:
                                add_candidate(src, "video.currentSrc")
                        except Exception:
                            pass

                        # Also harvest <source src> and og:video meta tags.
                        try:
                            extras = await page.evaluate(
                                """() => {
                                    const out = [];
                                    document.querySelectorAll('source[src]').forEach(s => out.push(s.src));
                                    document.querySelectorAll('meta[property="og:video"], meta[property="og:video:url"], meta[name="twitter:player:stream"]').forEach(m => {
                                        const c = m.getAttribute('content');
                                        if (c) out.push(c);
                                    });
                                    return out;
                                }"""
                            )
                            for src in extras or []:
                                add_candidate(src, "source/meta")
                        except Exception:
                            pass

                        if candidates:
                            break

                    # A second pass can expose lazy-loaded media.
                    try:
                        await page.evaluate(
                            """() => {
                                document.querySelectorAll('video').forEach(v => {
                                    try {
                                        v.scrollIntoView({block:'center'});
                                        v.muted = true;
                                        v.playsInline = true;
                                        const p = v.play();
                                        if (p && p.catch) p.catch(() => {});
                                    } catch(e) {}
                                });
                            }"""
                        )
                        await page.wait_for_timeout(3000)
                        srcs = await page.evaluate(
                            """() => Array.from(document.querySelectorAll('video'))
                                .map(v => v.currentSrc || v.src || '')
                                .filter(Boolean)"""
                        )
                        for src in srcs or []:
                            add_candidate(src, "video.currentSrc-after-play")
                    except Exception:
                        pass

                    if candidates:
                        break

                # Prioritize direct X video CDN URLs and HLS manifests.
                candidates.sort(
                    key=lambda item: (
                        0 if "video.twimg.com" in item[0].lower() else 1,
                        0 if ".mp4" in item[0].lower() else 1,
                        0 if ".m3u8" in item[0].lower() else 1,
                    )
                )

                if not candidates:
                    print("  [i] BROWSER FALLBACK: no video stream URL detected.")
                    return []

                base_name = safe_filename(
                    f"{platform_username_from_url(url, platform) or username or 'media'}_{timestamp_str}"
                )

                # Try the captured response body first when it is a complete direct video response.
                for resp, ct in response_candidates:
                    try:
                        ru = resp.url
                        low = ru.lower()
                        if not any(x in low for x in (".mp4", ".m4v", ".mov", ".webm")) and "video/" not in ct:
                            continue
                        body = await resp.body()
                        if body and len(body) >= 32 * 1024:
                            target = dest / f"{base_name}_Video.mp4"
                            target.write_bytes(body)
                            if _valid_video_file(str(target)):
                                print(f"  [+] BROWSER FALLBACK: recovered video response → {target.name}")
                                return [target]
                            try:
                                target.unlink()
                            except Exception:
                                pass
                    except Exception:
                        continue

                # Then download the best candidate using the browser's session cookies.
                cookie_header = _cookie_header(cookies)
                referer = url
                ffmpeg = get_ffmpeg_executable()

                for media_url, kind in candidates:
                    low = media_url.lower().split("?", 1)[0]
                    target = dest / f"{base_name}_Video.mp4"

                    # HLS/DASH: let FFmpeg fetch the manifest with the same session headers.
                    if (".m3u8" in low or ".mpd" in low) and ffmpeg:
                        headers_text = _media_headers(referer, cookies=cookies)
                        cmd = [
                            ffmpeg, "-y",
                            "-headers", headers_text,
                            "-protocol_whitelist", "file,http,https,tcp,tls,crypto",
                            "-i", media_url,
                            "-c", "copy",
                            "-movflags", "+faststart",
                            str(target),
                        ]
                        try:
                            r = subprocess.run(
                                cmd,
                                stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE,
                                timeout=1800,
                            )
                            if r.returncode == 0 and _valid_video_file(str(target)):
                                print(f"  [+] BROWSER FALLBACK: HLS/DASH recovered → {target.name}")
                                return [target]
                        except Exception as e:
                            print(f"  [i] Browser HLS fallback failed: {e}")
                        try:
                            if target.exists():
                                target.unlink()
                        except Exception:
                            pass
                        continue

                    # Direct progressive video URL.
                    if any(x in low for x in (".mp4", ".m4v", ".mov", ".webm", ".mkv")) or "video.twimg.com" in low:
                        try:
                            import requests
                            headers = {
                                "User-Agent": S24_CHROME_UA,
                                "Accept": "*/*",
                                "Accept-Language": "en-US,en;q=0.9",
                                "Referer": referer,
                            }
                            if cookie_header:
                                headers["Cookie"] = cookie_header

                            with requests.get(
                                media_url,
                                headers=headers,
                                stream=True,
                                timeout=(30, 120),
                                allow_redirects=True,
                            ) as rr:
                                rr.raise_for_status()
                                with open(target, "wb") as fh:
                                    for chunk in rr.iter_content(chunk_size=1024 * 1024):
                                        if chunk:
                                            fh.write(chunk)
                            if _valid_video_file(str(target)):
                                print(f"  [+] BROWSER FALLBACK: direct video recovered → {target.name}")
                                return [target]
                        except Exception as e:
                            print(f"  [i] Browser direct-video download failed: {e}")
                        try:
                            if target.exists():
                                target.unlink()
                        except Exception:
                            pass

                print("  [i] BROWSER FALLBACK: detected media URLs, but none could be downloaded.")
                return []
            finally:
                for ctx in contexts:
                    try:
                        await ctx.close()
                    except Exception:
                        pass
                try:
                    await browser.close()
                except Exception:
                    pass
    except Exception as e:
        print(f"  [i] BROWSER FALLBACK safely skipped: {type(e).__name__}: {e}")
        return []


def browser_network_video_fallback(
    url: str,
    dest_folder: Path,
    platform: str,
    username: str,
    timestamp_str: str,
) -> List[Path]:
    """Synchronous wrapper. Any browser failure is contained and returns []."""
    try:
        return asyncio.run(
            _browser_network_video_fallback_async(
                url, str(dest_folder), platform, username, timestamp_str
            )
        )
    except RuntimeError:
        # Handles a caller that already has an event loop.
        try:
            import threading
            result = []
            error = []

            def runner():
                try:
                    result.extend(asyncio.run(
                        _browser_network_video_fallback_async(
                            url, str(dest_folder), platform, username, timestamp_str
                        )
                    ))
                except Exception as e:
                    error.append(e)

            t = threading.Thread(target=runner, daemon=True)
            t.start()
            t.join(timeout=1900)
            if error:
                print(f"  [i] BROWSER FALLBACK thread failed safely: {error[0]}")
            return result
        except Exception as e:
            print(f"  [i] BROWSER FALLBACK wrapper failed safely: {e}")
            return []
    except Exception as e:
        print(f"  [i] BROWSER FALLBACK wrapper failed safely: {e}")
        return []



def download_media_from_url(url: str, dest_folder: Path) -> Tuple[List[Path], str, bool]:
    """Universal cookie-independent downloader with image recovery + permanent-error classification."""
    dest_folder = Path(dest_folder)
    dest_folder.mkdir(parents=True, exist_ok=True)
    platform = detect_platform(url)
    username = platform_username_from_url(url, platform)
    timestamp_str = datetime.now().strftime("%d_%b_%Y_%H-%M-%S")
    log_parts: List[str] = []

    def _merge_log(*chunks: str) -> str:
        for chunk in chunks:
            if chunk and str(chunk).strip():
                log_parts.append(str(chunk).strip())
        return "\n".join(log_parts)

    # Snapshot BEFORE the engine. Some yt-dlp versions successfully finish an
    # FFmpeg merge but return no filepath in the Python API. The recovery scan
    # below prevents a successful download from being reported as a failure.
    before = {}
    try:
        for p in dest_folder.rglob("*"):
            if p.is_file() and p.suffix.lower() in ALL_EXT:
                st = p.stat()
                before[str(p.relative_to(dest_folder)).lower()] = (st.st_mtime_ns, st.st_size)
    except Exception:
        pass

    print_step("~", f"Universal video engine → {platform}: {url[:100]}", C.CYAN)
    try:
        saved, engine_log = run_yt_dlp_download(
            url=url, output_dir=str(dest_folder), platform=platform,
            cookies=None, username=username, timestamp_str=timestamp_str,
        )
        _merge_log(engine_log)
        saved_paths = [Path(p) for p in saved if p and Path(p).exists()]

        # Recovery #1: the universal engine may have completed a file but
        # returned no filepath/result after FFmpeg finalization.
        if not saved_paths:
            recovered = _collect_new_media(dest_folder, before)
            if recovered:
                saved_paths = recovered
                print_step("+", f"Recovered {len(saved_paths)} completed download(s) from output folder", C.GREEN)

        # Recovery #2: use the bundled yt-dlp executable once, directly in
        # the destination. This fixes the Python-API/CLI result mismatch seen
        # when the console reaches 100% merging but returns an empty list.
        if not saved_paths:
            fallback_saved, fallback_log = _last_resort_ytdlp_cli(
                url, str(dest_folder), platform, username, timestamp_str
            )
            _merge_log(fallback_log)
            if fallback_saved:
                saved_paths = fallback_saved
                print_step("+", f"Recovered {len(saved_paths)} file(s) using final yt-dlp executable fallback", C.GREEN)

        if saved_paths:
            for p in saved_paths:
                print_step("+", f"Universal engine saved → {p.name}", C.GREEN)
            return saved_paths, "universal video engine: success", False

        # Recovery #3: full gallery-dl download (images + any non-video media).
        # yt-dlp "No video could be found" often means an image/GIF post.
        print_step("~", "No video recovered — trying gallery-dl for images/other media...", C.CYAN)
        try:
            before_gallery = _snapshot_files(dest_folder)
            gallery_media, gallery_log = download_via_gallery_dl(url, dest_folder)
            _merge_log(gallery_log)
            if not gallery_media:
                gallery_media = _collect_new_media(dest_folder, before_gallery)
            if gallery_media:
                for p in gallery_media:
                    print_step("+", f"gallery-dl saved → {p.name}", C.GREEN)
                return gallery_media, "gallery-dl image/media recovery: success", False
        except Exception as gallery_err:
            _merge_log(f"gallery-dl recovery failed: {gallery_err}")
            print_step("~", f"gallery-dl recovery skipped: {gallery_err}", C.YELLOW)

        # Recovery #4: yt-dlp thumbnail / still-image pass (legacy helper).
        try:
            thumb_media, thumb_log = download_via_ytdlp(url, dest_folder)
            _merge_log(thumb_log)
            if thumb_media:
                for p in thumb_media:
                    print_step("+", f"yt-dlp still/thumbnail saved → {p.name}", C.GREEN)
                return thumb_media, "yt-dlp still/thumbnail recovery: success", False
        except Exception as thumb_err:
            _merge_log(f"yt-dlp still recovery failed: {thumb_err}")

        # FINAL ENGINE E: real-browser/network fallback (X uses embed URL first).
        print_step("~", "No-cookie extractors found no media — starting browser/network fallback...", C.CYAN)
        try:
            browser_saved = browser_network_video_fallback(
                url=url,
                dest_folder=dest_folder,
                platform=platform,
                username=username,
                timestamp_str=timestamp_str,
            )
        except Exception as browser_err:
            browser_saved = []
            _merge_log(f"browser fallback exception: {browser_err}")
            print_step("~", f"Browser fallback safely skipped: {browser_err}", C.YELLOW)

        if browser_saved:
            for p in browser_saved:
                print_step("+", f"Browser fallback saved original video → {Path(p).name}", C.GREEN)
            return (
                [Path(p) for p in browser_saved if Path(p).exists()],
                "browser network fallback: success",
                False,
            )

        _merge_log("universal media engine: no media extracted after all fallbacks")
        combined = "\n".join(log_parts)
        permanent = _looks_permanent_download_error(combined)
        return [], combined, permanent
    except Exception as e:
        log = f"universal video engine failed: {type(e).__name__}: {e}"
        _merge_log(log)
        combined = "\n".join(log_parts) if log_parts else log
        print_step("!", log, C.YELLOW)
        return [], combined, _looks_permanent_download_error(combined)


_EXIF_DATE_TAGS = (36867, 36868, 306)
_DATE_STRING_FORMATS = (
    "%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S",
    "%Y-%m-%dT%H:%M:%S.%fZ", "%Y-%m-%dT%H:%M:%SZ",
    "%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S",
    "%Y:%m:%d", "%Y-%m-%d",
)
_MP4_EPOCH = datetime(1904, 1, 1, tzinfo=timezone.utc)


def _parse_date_string(value) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, bytes):
        try:
            value = value.decode("utf-8", errors="ignore")
        except Exception:
            return None
    if not isinstance(value, str):
        value = str(value)
    s = value.strip().strip("\x00").strip().strip('"').strip("'")
    if not s:
        return None
    for fmt in _DATE_STRING_FORMATS:
        try:
            probe = s[:26].rstrip("Z") if ("T" in s or "Z" in s or ":" in s[:5]) else s[:19]
            dt = datetime.strptime(probe, fmt.rstrip("Z") if fmt.endswith("Z") else fmt)
            return dt.timestamp()
        except Exception:
            continue
    m = re.match(
        r"(\d{4})[:\-/.](\d{1,2})[:\-/.](\d{1,2})(?:[ T](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?",
        s,
    )
    if m:
        try:
            y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            hh, mm, ss = int(m.group(4) or 0), int(m.group(5) or 0), int(m.group(6) or 0)
            return datetime(y, mo, d, hh, mm, ss).timestamp()
        except Exception:
            pass
    return None


def _mp4_seconds_to_unix(seconds: int) -> Optional[float]:
    try:
        if seconds is None or seconds <= 60:
            return None
        dt = _MP4_EPOCH.timestamp() + float(seconds)
        if 0 < dt < 4102444800:
            return dt
    except Exception:
        pass
    return None


def _read_image_exif_date_created(path: Path) -> Tuple[Optional[float], str]:
    try:
        with Image.open(path) as im:
            try:
                exif = im.getexif()
            except Exception:
                exif = None
            if not exif:
                return None, ""
            ifd = None
            try:
                if hasattr(exif, "get_ifd"):
                    ifd = exif.get_ifd(0x8769)
            except Exception:
                ifd = None
            labels = {
                36867: "EXIF Date created (DateTimeOriginal)",
                36868: "EXIF DateTimeDigitized",
                306: "EXIF DateTime",
            }
            for tag_id in _EXIF_DATE_TAGS:
                raw = None
                if ifd is not None and tag_id in (36867, 36868):
                    try:
                        raw = ifd.get(tag_id)
                    except Exception:
                        raw = None
                if raw is None:
                    try:
                        raw = exif.get(tag_id)
                    except Exception:
                        raw = None
                ts = _parse_date_string(raw)
                if ts is not None:
                    return ts, labels.get(tag_id, "EXIF")
    except Exception:
        pass
    return None, ""


def _read_mp4_creation_time(path: Path) -> Optional[float]:
    try:
        with open(path, "rb") as f:
            file_size = path.stat().st_size
            pos = 0
            max_scan = min(file_size, 8 * 1024 * 1024)
            while pos + 8 <= max_scan:
                f.seek(pos)
                header = f.read(8)
                if len(header) < 8:
                    break
                size, atom = struct.unpack(">I4s", header)
                try:
                    atom_type = atom.decode("latin-1")
                except Exception:
                    atom_type = ""
                header_len = 8
                if size == 1:
                    ext = f.read(8)
                    if len(ext) < 8:
                        break
                    size = struct.unpack(">Q", ext)[0]
                    header_len = 16
                elif size == 0:
                    size = file_size - pos
                if size < header_len:
                    break
                if atom_type == "moov":
                    end = pos + size
                    inner = pos + header_len
                    while inner + 8 <= end and inner < max_scan + 2_000_000:
                        f.seek(inner)
                        h2 = f.read(8)
                        if len(h2) < 8:
                            break
                        s2, a2 = struct.unpack(">I4s", h2)
                        try:
                            t2 = a2.decode("latin-1")
                        except Exception:
                            t2 = ""
                        h2_len = 8
                        if s2 == 1:
                            e2 = f.read(8)
                            if len(e2) < 8:
                                break
                            s2 = struct.unpack(">Q", e2)[0]
                            h2_len = 16
                        elif s2 == 0:
                            s2 = end - inner
                        if s2 < h2_len:
                            break
                        if t2 == "mvhd":
                            f.seek(inner + h2_len)
                            version_flags = f.read(4)
                            if len(version_flags) < 4:
                                break
                            version = version_flags[0]
                            if version == 1:
                                data = f.read(16)
                                if len(data) >= 16:
                                    return _mp4_seconds_to_unix(int(struct.unpack(">Q", data[0:8])[0]))
                            else:
                                data = f.read(8)
                                if len(data) >= 8:
                                    return _mp4_seconds_to_unix(int(struct.unpack(">I", data[0:4])[0]))
                            return None
                        if t2 in ("trak", "mdia", "minf", "stbl", "udta", "meta"):
                            inner += h2_len
                            continue
                        inner += s2
                    return None
                pos += size
    except Exception:
        pass
    return None


def _find_ffprobe() -> Optional[str]:
    for p in FFPROBE_CANDIDATES:
        try:
            if p.exists():
                return str(p)
        except Exception:
            pass
    for name in ("ffprobe.exe", "ffprobe"):
        found = shutil.which(name)
        if found:
            return found
    return None


def _read_ffprobe_creation_time(path: Path) -> Optional[float]:
    ffprobe = _find_ffprobe()
    if not ffprobe:
        return None
    try:
        cmd = [
            ffprobe, "-v", "quiet", "-print_format", "json",
            "-show_entries", "format_tags=creation_time:stream_tags=creation_time",
            str(path),
        ]
        proc = subprocess.run(
            cmd, capture_output=True, text=True, encoding="utf-8",
            errors="replace", timeout=20,
        )
        if proc.returncode != 0 or not (proc.stdout or "").strip():
            return None
        data = json.loads(proc.stdout)
        tags = (data.get("format") or {}).get("tags") or {}
        for key in ("creation_time", "Creation Time", "DATE", "date",
                    "com.apple.quicktime.creationdate"):
            if key in tags:
                ts = _parse_date_string(str(tags[key]))
                if ts is not None:
                    return ts
        for stream in data.get("streams") or []:
            stags = stream.get("tags") or {}
            for key in ("creation_time", "Creation Time", "DATE", "date",
                        "com.apple.quicktime.creationdate"):
                if key in stags:
                    ts = _parse_date_string(str(stags[key]))
                    if ts is not None:
                        return ts
    except Exception:
        pass
    return None


def _read_video_media_date_created(path: Path) -> Tuple[Optional[float], str]:
    ts = _read_ffprobe_creation_time(path)
    if ts is not None:
        return ts, "Media Date created (metadata)"
    if path.suffix.lower() in {".mp4", ".m4v", ".mov", ".3gp", ".qt"}:
        ts = _read_mp4_creation_time(path)
        if ts is not None:
            return ts, "Media Date created (MP4/MOV container)"
    return None, ""


def _read_audio_tag_date(path: Path) -> Tuple[Optional[float], str]:
    if not HAS_MUTAGEN:
        return None, ""
    try:
        audio = MutagenFile(path, easy=True)
        if audio is None:
            return None, ""
        tags = getattr(audio, "tags", None) or {}
        for key in ("date", "year", "originaldate", "creation_time"):
            val = None
            try:
                if key in tags:
                    v = tags[key]
                    val = v[0] if isinstance(v, (list, tuple)) and v else v
            except Exception:
                val = None
            if val:
                s = str(val).strip()
                if re.fullmatch(r"\d{4}", s):
                    try:
                        return datetime(int(s), 1, 1).timestamp(), f"Audio tag date ({key})"
                    except Exception:
                        pass
                ts = _parse_date_string(s)
                if ts is not None:
                    return ts, f"Audio tag date ({key})"
    except Exception:
        pass
    return None, ""


def _filesystem_date_created(path: Path) -> Tuple[Optional[float], str]:
    try:
        st = path.stat()
        birth = getattr(st, "st_birthtime", None)
        if birth is not None:
            return float(birth), "File Date created (birthtime)"
        return float(st.st_ctime), "File Date created"
    except Exception:
        return None, ""


def get_media_sort_timestamp(path: Path) -> Tuple[float, str, str]:
    name_key = path.name.lower()
    ext = path.suffix.lower()
    if ext in IMAGE_EXT:
        ts, source = _read_image_exif_date_created(path)
        if ts is not None:
            return (ts, source, name_key)
    elif ext in VIDEO_EXT:
        ts, source = _read_video_media_date_created(path)
        if ts is not None:
            return (ts, source, name_key)
    elif ext in AUDIO_EXT:
        ts, source = _read_audio_tag_date(path)
        if ts is not None:
            return (ts, source, name_key)
    ts, source = _filesystem_date_created(path)
    if ts is not None:
        return (ts, source, name_key)
    try:
        return (path.stat().st_mtime, "mtime", name_key)
    except Exception:
        return (0.0, "unknown", name_key)


def format_ts(ts: float) -> str:
    try:
        return datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return "?"



_SCREENSHOT_EXCLUDED_SUFFIXES = (
    "_Video2GreenScreen.png",
    "_GREEN_VIDEO.png",
)

def _is_generated_screenshot(path):
    name = Path(path).name
    return (
        name.endswith(_SCREENSHOT_EXCLUDED_SUFFIXES)
        or "_slide" in name.lower() and name.lower().endswith(".png")
        or "Post_Saved_On" in name
    )

def discover_media(root: Path) -> List[Path]:
    try:
        found = []
        for i in root.iterdir():
            if not i.is_file():
                continue
            if i.suffix.lower() not in ALL_EXT:
                continue
            if _is_already_named_output(i.name):
                continue
            found.append(i)
    except Exception as e:
        log_error(f"discover: {e}")
        return []
    if not found:
        return []
    print(f"  {C.DIM}Sorting media by Date created (earliest first)...{C.RESET}")
    keyed = []
    for p in found:
        ts, source, name_key = get_media_sort_timestamp(p)
        keyed.append((ts, name_key, p, source))
        print(f"      {C.DIM}{p.name}  →  {format_ts(ts)}  [{source}]{C.RESET}")
    keyed.sort(key=lambda item: (item[0], item[1]))
    sorted_paths = [item[2] for item in keyed]
    print(f"  {C.GREEN}[OK] Order locked: earliest Date created → latest ({len(sorted_paths)} file(s)){C.RESET}\n")
    return sorted_paths


def img_to_base64(img):
    try:
        buf = BytesIO()
        img.save(buf, format="JPEG", quality=85)
        return base64.b64encode(buf.getvalue()).decode("utf-8")
    except Exception as e:
        log_error(f"img_to_base64: {e}")
        return None


def translate_to_english_if_needed(original_text):
    if not original_text:
        return original_text, "Not Required"
    prompt = f"""Analyze the text.
1. Return the EXACT original text unchanged in the 'original' field.
2. STRICT RULE: If the text is ALREADY IN ENGLISH, put exactly "Not Required" in the 'english' field.
3. If the text is NOT in English, translate it to English and put it in the 'english' field.
Return ONLY valid JSON (no markdown, no commentary): {{"original": "...", "english": "..."}}

Text: {json.dumps(original_text, ensure_ascii=False)}
"""
    tokens_hint = estimate_tokens_from_text(prompt) + 500
    try:
        def make_fn(model_id: str):
            def _op(client: OpenAI):
                return chat_completions_create(
                    client,
                    model=model_id,
                    messages=[{"role": "user", "content": prompt}],
                    temperature=0.1,
                    max_completion_tokens=4000,
                    timeout=45.0,
                    response_format={"type": "json_object"},
                )
            return _op
        resp = call_with_model_fallback("translate", "translate", make_fn, tokens_hint=tokens_hint)
        raw = message_text_from_response(resp)
        data = extract_json_object(raw)
        if data:
            orig = data.get("original", original_text)
            eng = normalize_english_field(str(orig), str(data.get("english", "")))
            return orig, eng
        print(f"            {C.YELLOW}translate JSON parse failed; raw[:200]={raw[:200]!r}{C.RESET}")
    except Exception as e:
        log_error(f"translate: {e}")
        print(f"            {C.YELLOW}translate error: {e}{C.RESET}")
    return original_text, "Not Required"


def _get_media_duration_seconds(fp: Path) -> float:
    for probe in FFPROBE_CANDIDATES:
        try:
            if not probe.exists():
                continue
            proc = subprocess.run(
                [str(probe), "-v", "error", "-show_entries", "format=duration",
                 "-of", "default=noprint_wrappers=1:nokey=1", str(fp)],
                capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=30,
            )
            value = (proc.stdout or "").strip()
            if value:
                duration = float(value)
                if duration > 0:
                    return duration
        except Exception:
            continue
    return 0.0


def _merge_whisper_chunks(parts: List[str]) -> str:
    merged = ""
    for part in parts:
        part = (part or "").strip()
        if not part:
            continue
        if not merged:
            merged = part
            continue
        left = re.findall(r"\S+", merged)
        right = re.findall(r"\S+", part)
        max_overlap = min(30, len(left), len(right))
        overlap = 0
        for n in range(max_overlap, 0, -1):
            a = [re.sub(r"[^\w']+", "", w).lower() for w in left[-n:]]
            b = [re.sub(r"[^\w']+", "", w).lower() for w in right[:n]]
            if a and a == b:
                overlap = n
                break
        if overlap:
            part = " ".join(right[overlap:]).strip()
        if part:
            merged = merged.rstrip() + " " + part
    return merged.strip()


def get_audio_text(fp: Path):
    if not FFMPEG_PATH.exists():
        print(f"            {C.YELLOW}ffmpeg missing{C.RESET}")
        return None

    safe_stem = re.sub(r"[^\w\-]+", "_", fp.stem)[:80]
    temp_wav = MEDIA_DIR / f"temp_audio_{safe_stem}.wav"
    chunk_dir = MEDIA_DIR / f"temp_whisper_{safe_stem}"
    chunk_dir.mkdir(parents=True, exist_ok=True)

    CHUNK_SECONDS = 8 * 60
    OVERLAP_SECONDS = 2

    try:
        duration = _get_media_duration_seconds(fp)
        if duration > 0:
            print(f"            {C.DIM}Media duration: {duration / 60:.2f} min{C.RESET}")
        else:
            print(f"            {C.YELLOW}Could not read duration; processing as one audio stream{C.RESET}")

        print(f"            {C.DIM}[1/3] Extracting FULL audio (no 60-second limit)...{C.RESET}")
        extract_proc = subprocess.run(
            [str(FFMPEG_PATH), "-y", "-i", str(fp), "-vn", "-acodec", "pcm_s16le",
             "-ar", "16000", "-ac", "1", str(temp_wav)],
            capture_output=True, timeout=max(120, int((duration or 60) + 120)),
            text=True, encoding="utf-8", errors="replace",
        )
        if extract_proc.returncode != 0 or not temp_wav.exists() or temp_wav.stat().st_size == 0:
            log_error(f"audio extraction failed: {extract_proc.stderr[-2000:]}")
            return None

        actual_duration = duration or (temp_wav.stat().st_size / (16000 * 2))
        if actual_duration <= CHUNK_SECONDS:
            chunk_paths = [temp_wav]
        else:
            chunk_paths = []
            start = 0.0
            chunk_index = 1
            while start < actual_duration:
                end = min(actual_duration, start + CHUNK_SECONDS)
                chunk_path = chunk_dir / f"chunk_{chunk_index:04d}.wav"
                print_step("~", f"Preparing Whisper chunk {chunk_index}: {start/60:.2f}–{end/60:.2f} min", C.DIM)
                proc = subprocess.run(
                    [str(FFMPEG_PATH), "-y", "-ss", f"{start:.3f}", "-i", str(temp_wav),
                     "-t", f"{(end - start):.3f}", "-acodec", "copy", str(chunk_path)],
                    capture_output=True, timeout=120, text=True,
                    encoding="utf-8", errors="replace",
                )
                if proc.returncode != 0 or not chunk_path.exists() or chunk_path.stat().st_size == 0:
                    proc = subprocess.run(
                        [str(FFMPEG_PATH), "-y", "-ss", f"{start:.3f}", "-i", str(temp_wav),
                         "-t", f"{(end - start):.3f}", "-acodec", "pcm_s16le", "-ar", "16000", "-ac", "1",
                         str(chunk_path)],
                        capture_output=True, timeout=180, text=True,
                        encoding="utf-8", errors="replace",
                    )
                if proc.returncode != 0 or not chunk_path.exists() or chunk_path.stat().st_size == 0:
                    raise RuntimeError(f"Could not create Whisper chunk {chunk_index}: {proc.stderr[-1000:]}")
                chunk_paths.append(chunk_path)
                if end >= actual_duration:
                    break
                start = max(0.0, end - OVERLAP_SECONDS)
                chunk_index += 1

        print(f"            {C.DIM}[2/3] Transcribing {len(chunk_paths)} audio chunk(s) with Whisper...{C.RESET}")
        transcripts = []
        total_chunks = len(chunk_paths)

        for idx, chunk_path in enumerate(chunk_paths, 1):
            try:
                fsz = chunk_path.stat().st_size
                tokens_hint = max(200, min(8000, fsz // 50))
            except Exception:
                tokens_hint = 1000

            print_step("~", f"Whisper {idx}/{total_chunks}: {chunk_path.name}", C.DIM)

            def make_fn(model_id: str, audio_path: Path = chunk_path):
                def _op(client: OpenAI):
                    with open(audio_path, "rb") as audio_file:
                        return client.audio.transcriptions.create(
                            model=model_id, file=audio_file, response_format="json",
                        )
                return _op

            resp = call_with_model_fallback(
                "whisper", "whisper", make_fn, tokens_hint=tokens_hint
            )
            text = (getattr(resp, "text", None) or "").strip()
            if text:
                transcripts.append(text)

        text = _merge_whisper_chunks(transcripts)
        return text or None

    except Exception as e:
        log_error(f"audio: {e}\n{traceback.format_exc()}")
        print(f"            {C.RED}audio error: {e}{C.RESET}")
        return None
    finally:
        try:
            if temp_wav.exists():
                temp_wav.unlink()
        except Exception:
            pass
        try:
            if chunk_dir.exists():
                shutil.rmtree(chunk_dir, ignore_errors=True)
        except Exception:
            pass


EXTRACTION_PROMPT = """Extract details from this social media image/screenshot.

Return ONLY a single valid JSON object. No markdown fences. No commentary before or after.
Use exactly these keys:
{
  "author_name": "Display name or empty string",
  "author_handle": "username/handle or empty string",
  "post_text": "EXACT original on-screen post text (do not translate)",
  "post_text_english": "If post_text is already English: exactly Not Required. If not English: full English translation.",
  "date_text": "Date/time visible on screen or empty string"
}

Rules:
- post_text must be the original language text as shown.
- If no text is visible, use empty strings and post_text_english = "Not Required".
- Do not invent authors or dates that are not visible.
- Do not wrap JSON in ``` fences.
"""


def extract_text_from_image(b64: str):
    try:
        tokens_hint = estimate_tokens_from_text(EXTRACTION_PROMPT) + max(800, len(b64) // 10)

        def make_fn(model_id: str):
            def _op(client: OpenAI):
                messages = [{
                    "role": "user",
                    "content": [
                        {"type": "text", "text": EXTRACTION_PROMPT},
                        {"type": "image_url", "image_url": {"url": f"data:image/jpeg;base64,{b64}"}},
                    ],
                }]
                return chat_completions_create(
                    client,
                    model=model_id,
                    messages=messages,
                    temperature=0.1,
                    max_completion_tokens=4000,
                    timeout=90.0,
                    response_format={"type": "json_object"},
                )
            return _op

        resp = call_with_model_fallback("image OCR", "vision", make_fn, tokens_hint=tokens_hint)
        raw = message_text_from_response(resp)
        if not raw.strip():
            print(f"            {C.RED}OCR empty response from model{C.RESET}")
            log_error("image OCR: empty content")
            return None

        data = extract_json_object(raw)
        if data:
            orig = data.get("post_text", "") or ""
            eng = normalize_english_field(str(orig), str(data.get("post_text_english", "")))
            data["post_text"] = orig
            data["post_text_english"] = eng
            data.setdefault("author_name", "")
            data.setdefault("author_handle", "")
            data.setdefault("date_text", "")
            preview = (orig or "")[:120].replace("\n", " ")
            print(f"            {C.GREEN}OCR ok — author={data.get('author_name')!r} text[:120]={preview!r}{C.RESET}")
            return data

        print(f"            {C.RED}OCR JSON parse failed{C.RESET}")
        print(f"            {C.DIM}raw[:400]={raw[:400]!r}{C.RESET}")
        log_error(f"image OCR: JSON parse failed. raw[:800]={raw[:800]!r}")
    except Exception as e:
        log_error(f"image OCR: {e}\n{traceback.format_exc()}")
        print(f"            {C.RED}OCR exception: {e}{C.RESET}")
    return None


def _author_url_from_source_url(source_url: str, data: dict) -> str:
    """Derive an author/profile URL when the source URL itself identifies it."""
    source_url = (source_url or "").strip()
    if not source_url:
        return ""
    try:
        parsed = urlparse(source_url)
        host = (parsed.hostname or "").lower()
        parts = [p for p in parsed.path.split("/") if p]
        if host in ("x.com", "twitter.com") and parts:
            if parts[0].lower() not in ("i", "home", "explore", "search"):
                return f"https://{host}/{parts[0]}"
        if host in ("instagram.com", "www.instagram.com") and parts:
            if parts[0].lower() not in ("p", "reel", "reels", "tv", "stories", "explore"):
                return f"https://www.instagram.com/{parts[0]}/"
    except Exception:
        pass

    handle = str(data.get("author_handle") or "").strip().lstrip("@")
    if handle and handle.lower() not in ("user", "unknown"):
        try:
            parsed = urlparse(source_url)
            host = (parsed.hostname or "").lower()
            if host in ("x.com", "twitter.com"):
                return f"https://x.com/{handle}"
            if host in ("instagram.com", "www.instagram.com"):
                return f"https://www.instagram.com/{handle}/"
        except Exception:
            pass
    return ""


def get_formatted_text_block(data: dict) -> str:
    source_url = str(data.get("source_url") or _ACTIVE_SOURCE_URL or "").strip()
    author_name = str(data.get("author_name") or "Unknown").strip()
    author_handle = str(data.get("author_handle") or "user").strip()
    author_url = str(data.get("author_url") or _author_url_from_source_url(source_url, data)).strip()
    return f"""DOWNLOAD DATE: {datetime.now().strftime("%d %b %Y; %H:%M")}

ORIGINAL URL OF CONTENT: {source_url}

AUTHOR: {author_name} ({author_handle})

AUTHOR URL : {author_url}

CONTENT PUBLISH DATE & TIME : {data.get('date_text', 'Unknown')}

Extracted text from Post(s):

Original Language Text: {data.get('post_text', '')}

English Translated Text: {data.get('post_text_english', 'Not Required')}
"""


def append_to_combine_log(data, title: str, log_path: Path):
    try:
        with open(log_path, "a", encoding="utf-8-sig") as f:
            f.write(f"{'=' * 80}\n{title}\n{'=' * 80}\n")
            f.write(get_formatted_text_block(data))
            f.write("\n\n")
    except Exception as e:
        log_error(f"append combine log: {e}")


def unique_dest(folder: Path, filename: str) -> Path:
    dest = folder / filename
    if not dest.exists():
        return dest
    stem = Path(filename).stem
    ext = Path(filename).suffix
    n = 1
    while True:
        cand = folder / f"{stem}_{n}{ext}"
        if not cand.exists():
            return cand
        n += 1


def _starting_counters(folders: dict) -> dict:
    counters = {"Image": 0, "Video": 0, "Audio": 0}
    for f_type, folder in folders.items():
        if not folder.exists():
            continue
        try:
            for p in folder.iterdir():
                if not p.is_file():
                    continue
                m = _RE_DONE_NAME.match(p.name)
                if m and m.group(1).lower() == f_type.lower():
                    counters[f_type] = max(counters[f_type], int(m.group(2)))
        except Exception:
            pass
    return counters


def run_scraper(only_files: Optional[List[Path]] = None, output_prefix: Optional[str] = None, output_root: Optional[Path] = None, drive_doc_mode: bool = False) -> Tuple[int, int]:
    files = [p for p in only_files if not _is_generated_screenshot(p)] if only_files is not None else discover_media(MEDIA_DIR)
    if only_files is not None:
        keyed = []
        for p in only_files:
            if not p.exists() or p.suffix.lower() not in ALL_EXT:
                continue
            ts, source, name_key = get_media_sort_timestamp(p)
            keyed.append((ts, name_key, p))
        keyed.sort(key=lambda item: (item[0], item[1]))
        files = [item[2] for item in keyed]

    if not files:
        print(f"\n  {C.YELLOW}No media files in media folder:\n  {MEDIA_DIR}{C.RESET}")
        return 0, 0

    base = output_root or MEDIA_DIR
    if output_prefix and drive_doc_mode:
        # Google-Doc jobs: ONLY two folders and two scraper logs.
        # Audio files are treated as Video outputs and therefore go to the
        # Video folder/log. The master URL-picker workflow is unaffected.
        stem = _safe_folder_component(output_prefix)
        folders = {
            "Image": base / f"{stem} Image Scraper",
            "Video": base / f"{stem} Video Scraper",
        }
        logs = {
            "Image": base / f"{stem} Image Scraper.txt",
            "Video": base / f"{stem} Video Scraper.txt",
        }
    elif output_prefix:
        folders = {
            "Image": base / "Combined Image Scraper by AKT",
            "Video": base / "Combined Video Scraper by AKT",
            "Audio": base / "Combined Audio Scraper by AKT",
        }
        logs = {
            "Image": base / "Combine Image Scraper.txt",
            "Video": base / "Combine Video Scraper.txt",
            "Audio": base / "Combine Audio Scraper.txt",
        }
    for t in folders:
        folders[t].mkdir(parents=True, exist_ok=True)
    for log_path in logs.values():
        try:
            if not log_path.exists():
                open(log_path, "w", encoding="utf-8-sig").close()
        except Exception:
            pass
    for old in ("Image Scraper.txt", "Video Scraper.txt", "Audio Scraper.txt"):
        try:
            p = MEDIA_DIR / old
            if p.exists():
                p.unlink()
        except Exception:
            pass

    print(
        f"\n{C.CYAN}{C.BUILT_IN}{'=' * 60}\n"
        f"  SUPER SCRAPER v0.9 (multi-key Groq + Google Drive Priority + URL Picker)\n"
        f"  Media folder: {MEDIA_DIR}\n"
        f"  Found {len(files)} file(s)\n"
        f"  Sort: Date created FIRST (earliest → latest)\n"
        f"  Vision : {GROQ_MODELS.get('vision')}\n"
        f"  Translate: {GROQ_MODELS.get('translate')}\n"
        f"  Whisper: {GROQ_MODELS.get('whisper')}\n"
        f"  Key delay: {KEY_SWITCH_DELAY_SECONDS}s\n"
        f"  Logs: Combine Image/Video/Audio Scraper.txt\n"
        f"{'=' * 60}{C.RESET}\n"
    )
    if GROQ_KEY_MANAGER is not None:
        print(GROQ_KEY_MANAGER.status_summary())
        print()

    counters = _starting_counters(folders)
    success = 0
    failed = 0

    for fp in files:
        ext = fp.suffix.lower()
        if ext in IMAGE_EXT:
            f_type = "Image"
        elif ext in VIDEO_EXT:
            f_type = "Video"
        elif ext in AUDIO_EXT:
            # Google-Doc jobs intentionally have no Audio folder/log.
            # Put audio alongside videos and process it with the same text pipeline.
            f_type = "Video" if drive_doc_mode else "Audio"
        else:
            continue

        counters[f_type] += 1
        safe_name = re.sub(r'[<>:"/\\|?*]', "_", fp.name)
        new_name = f"{f_type} {counters[f_type]} {safe_name}"
        print(f"  {C.BUILT_IN}[{f_type} {counters[f_type]}] {fp.name}{C.RESET}")
        if GROQ_KEY_MANAGER is not None:
            print(f"            {C.DIM}key: {GROQ_KEY_MANAGER.current_label()}{C.RESET}")

        try:
            data = {
                "author_name": "Unknown",
                "author_handle": "user",
                "post_text": "",
                "post_text_english": "Not Required",
                "date_text": "Unknown",
                "source_url": _ACTIVE_SOURCE_URL,
                "author_url": "",
            }

            if f_type == "Image":
                print(f"            {C.CYAN}[OCR] Running Groq Vision OCR on {fp.name}...{C.RESET}")
                with Image.open(fp) as im:
                    img = im.convert("RGB")
                    if max(img.size) > 1600:
                        img.thumbnail((1600, 1600))
                    b64 = img_to_base64(img)
                if not b64:
                    print(f"            {C.RED}base64 encode failed{C.RESET}")
                else:
                    approx_bytes = (len(b64) * 3) // 4
                    print(f"            {C.DIM}image payload ~{approx_bytes/1024:.1f} KB{C.RESET}")
                    if approx_bytes > 3_500_000:
                        print(f"            {C.YELLOW}image large; re-encoding smaller...{C.RESET}")
                        with Image.open(fp) as im2:
                            img2 = im2.convert("RGB")
                            img2.thumbnail((1024, 1024))
                            buf = BytesIO()
                            img2.save(buf, format="JPEG", quality=70)
                            b64 = base64.b64encode(buf.getvalue()).decode("utf-8")
                    result = extract_text_from_image(b64)
                    if result:
                        data = result
                    else:
                        print(f"            {C.RED}OCR returned no data — check error_log.txt{C.RESET}")
                    gc.collect()

            elif f_type in ("Video", "Audio"):
                print(f"            {C.CYAN}[WHISPER] Extracting/transcribing full audio from {fp.name}...{C.RESET}")
                raw_text = get_audio_text(fp)
                if raw_text:
                    print(f"            {C.DIM}[3/3] Language check...{C.RESET}")
                    o, e = translate_to_english_if_needed(raw_text)
                    data["post_text"], data["post_text_english"] = o, e
                else:
                    data["post_text"] = "Could not extract audio/text."

            if not data.get("post_text"):
                data["post_text"] = "Could not extract text."
            if not data.get("post_text_english"):
                data["post_text_english"] = "Not Required"

            append_to_combine_log(data, new_name, logs[f_type])
            dest = unique_dest(folders[f_type], new_name)
            shutil.move(str(fp), str(dest))
            print(f"            {C.GREEN}OK → {folders[f_type].name}\\{dest.name}{C.RESET}")
            success += 1
        except Exception as e:
            log_error(f"{fp}: {e}\n{traceback.format_exc()}")
            print(f"            {C.RED}FAILED: {e}{C.RESET}")
            failed += 1
        time.sleep(1)

    if GROQ_KEY_MANAGER is not None:
        print()
        print(GROQ_KEY_MANAGER.status_summary())

    if drive_doc_mode:
        print(
            f"\n{C.GREEN}{C.BUILT_IN}{'=' * 60}\n"
            f"  SCRAPING COMPLETE!\n"
            f"  Google-Doc media folders (files only):\n"
            f"    {folders['Image']}\n"
            f"    {folders['Video']}\n"
            f"  Google-Doc logs:\n"
            f"    {logs['Image'].name}\n"
            f"    {logs['Video'].name}\n"
            f"  Audio files are stored in the Video folder/log.\n"
            f"{'=' * 60}{C.RESET}\n"
        )
    else:
        print(
            f"\n{C.GREEN}{C.BUILT_IN}{'=' * 60}\n"
            f"  SCRAPING COMPLETE!\n"
            f"  Media folders (files only):\n"
            f"    {folders['Image']}\n"
            f"    {folders['Video']}\n"
            f"    {folders['Audio']}\n"
            f"  Combine logs (outside):\n"
            f"    {logs['Image'].name}\n"
            f"    {logs['Video'].name}\n"
            f"    {logs['Audio'].name}\n"
            f"{'=' * 60}{C.RESET}\n"
        )
    return success, failed



def ensure_screenshot_environment() -> None:
    """Ensure Playwright Firefox exists in the same private AKT Tools folder."""
    os.makedirs(PW_BROWSERS, exist_ok=True)
    os.environ["PLAYWRIGHT_BROWSERS_PATH"] = PW_BROWSERS
    try:
        from playwright.sync_api import sync_playwright
    except Exception:
        print("  [WARN] Playwright is not importable; screenshot stage will be skipped.")
        return

    firefox_dir = os.path.join(PW_BROWSERS, "firefox")
    try:
        has_firefox = os.path.isdir(firefox_dir) and any(
            os.path.isdir(os.path.join(firefox_dir, x)) for x in os.listdir(firefox_dir)
        )
    except Exception:
        has_firefox = False

    if has_firefox:
        print("  [OK] Playwright Firefox browser binaries already present.")
        return

    print("  [..] Installing Playwright Firefox browser binaries (first run only)...")
    env = os.environ.copy()
    env["PYTHONPATH"] = SITE_PACKAGES + os.pathsep + env.get("PYTHONPATH", "")
    env["PLAYWRIGHT_BROWSERS_PATH"] = PW_BROWSERS
    try:
        subprocess.check_call(
            [sys.executable, "-m", "playwright", "install", "firefox"],
            env=env,
        )
        print("  [OK] Playwright Firefox browser binaries installed.")
    except Exception as e:
        print(f"  [WARN] Could not install Playwright Firefox: {e}")
        print("         Timestamped screenshot stage will continue as best-effort.")


